css.raster:
/* ═══════════════════════════════════════════════════════════════════
   RASTER, a monochrome, CSS-first design system.
   https://getraster.com

   One ink, no accent hue: emphasis comes from weight, size, and
   spacing. Hairline borders, a 204px module grid (184px column +
   20px gutter), sentence case everywhere.

   GENERATED from the css/ sources. Edit those, then run
   `npm run build:css`. Tokens come from src/tokens.ts.

   Typeface: Inter (SIL OFL 1.1), variable, latin + latin-ext.
   Bundled. System sans is fallback only.
   ═══════════════════════════════════════════════════════════════════ */

/* ── Inter ── SIL OFL 1.1. Variable, latin + latin-ext.
   System sans is fallback only (see body in base.css). */
@font-face{
  font-family:Inter;
  font-style:normal;
  font-weight:100 900;
  font-display:swap;
  src:url("./fonts/inter/InterVariable-latin-ext.woff2") format("woff2");
  unicode-range:U+0100-02BA,U+02BD-02C5,U+02C7-02CC,U+02CE-02D7,U+02DD-02FF,U+0304,U+0308,U+0329,U+1D00-1DBF,U+1E00-1E9F,U+1EF2-1EFF,U+2020,U+20A0-20AB,U+20AD-20C0,U+2113,U+2C60-2C7F,U+A720-A7FF
}
@font-face{
  font-family:Inter;
  font-style:normal;
  font-weight:100 900;
  font-display:swap;
  src:url("./fonts/inter/InterVariable-latin.woff2") format("woff2");
  unicode-range:U+0000-00FF,U+0131,U+0152-0153,U+02BB-02BC,U+02C6,U+02DA,U+02DC,U+0304,U+0308,U+0329,U+2000-206F,U+20AC,U+2122,U+2191,U+2193,U+2212,U+2215,U+FEFF,U+FFFD
}

/* ── Tokens ── GENERATED from src/tokens.ts. Do not edit by hand. */
:root {
  --bg: #FAF8F2;                        /* paper */
  --text: #1A1A1A;                      /* ink */
  --text-secondary: #6B6B6B;            /* gray */
  --accent: #1A1A1A;                   /* the "accent" is ink; monochrome */
  --divider: rgba(0,0,0,0.08);
  --divider-subtle: rgba(0,0,0,0.06);
  --table-alt: rgba(0,0,0,0.02);
  --grid-line: rgba(0,0,0,0.04);
  --radius-sm: 4px;           /* slight Raster radius; standalone buttons */
  --radius: var(--radius-sm);              /* alias — buttons, boxes, dialogs share it; cards stay 0 */
  --radius-chrome: 0px;
  --gutter: 20px;
  --pad: 20px;
  /* Concentric: Steve Ruiz innerRadius result. Closed form of the circular-corner fit. Default radius vs --pad is 0. */
  --radius-in: max(0px, calc(var(--radius) - var(--pad)));
  --ease: cubic-bezier(0.2, 0, 0, 1);
  --duration-snap: 0.12s;
  --duration: 0.18s;
  --duration-confirm: 0.16s;
  --transition: background-color var(--duration) var(--ease), color var(--duration) var(--ease);
  /* Background column grid: 204px modules (184 column + 20 gutter). */
  --grid-image: linear-gradient(to right,var(--grid-line) 0,var(--grid-line) 1px,transparent 1px,transparent 184px,var(--grid-line) 184px,var(--grid-line) 185px,transparent 185px,transparent 204px);
  --grid-size: 204px;
  --grid-pos: 20px 0;
  --text-scale: 1;
  /* Control scale. Desktop is the Raster poster; phone recuts in phone.css. */
  --hit: 40px;
  --control-h: 40px;
  --control-fs: 14px;
  --control-label: 12px;
}
[data-theme="dark"] {
  --bg: #0E0C0A;
  --text: #E8E8E8;
  --text-secondary: #949494;
  --accent: #E8E8E8;
  --divider: rgba(255,255,255,0.10);
  --divider-subtle: rgba(255,255,255,0.07);
  --table-alt: rgba(255,255,255,0.03);
  --grid-line: rgba(255,255,255,0.05);
}
/* Mobile grid (≤480): two fluid columns, three 25px gutters
   (edge · middle · edge). Column width = 50vw − 37.5px; the background
   draws all four column-edge lines and content lives between the outer pair. */
@media(max-width:480px){
  :root{
    --pad:25px;
    --grid-image:linear-gradient(to right,transparent 0,transparent 25px,var(--grid-line) 25px,var(--grid-line) 26px,transparent 26px,transparent calc(50vw - 12.5px),var(--grid-line) calc(50vw - 12.5px),var(--grid-line) calc(50vw - 11.5px),transparent calc(50vw - 11.5px),transparent calc(50vw + 12.5px),var(--grid-line) calc(50vw + 12.5px),var(--grid-line) calc(50vw + 13.5px),transparent calc(50vw + 13.5px),transparent calc(100vw - 26px),var(--grid-line) calc(100vw - 26px),var(--grid-line) calc(100vw - 25px),transparent calc(100vw - 25px));
    --grid-size:100vw;
    --grid-pos:0 0;
  }
}
/* Phone control scale (≤640): 44pt hits, 16px type on fields. */
@media(max-width:640px){
  :root{
    --hit:44px;
    --control-h:44px;
    --control-fs:16px;
    --control-label:15px;
  }
}

/* ── Base ──
   Raster owns the page: paper on html, ink on body, and quiet
   gutter verticals on html::before so overflow-x:clip cannot drop
   them. --grid-pos: 20px 0 puts the first tile line on the left
   20px gutter; that utmost left gutter must paint. Do not clip
   it. No 204 horizontals — those cage the type. Homepage and
   About kill this overlay and keep boxed cells only. */
html{scroll-behavior:smooth;font-size:16px;overflow-x:clip;background-color:var(--bg)}
html::before{
  content:"";
  position:fixed;
  inset:0;
  z-index:0;
  pointer-events:none;
  background-image:var(--grid-image);
  background-size:var(--grid-size) 100%;
  background-repeat:repeat-x;
  background-position:var(--grid-pos)
}
body{
  position:relative;
  z-index:1;
  overflow-x:clip;
  background-color:transparent;
  color:var(--text);
  font-family:Inter,-apple-system,BlinkMacSystemFont,'Segoe UI',system-ui,sans-serif;
  font-weight:500;
  line-height:1.6;
  transition:var(--transition);
  -webkit-font-smoothing:antialiased;
}

/* ── Utilities ── */
.rs-sr{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
.rs-sr:focus-visible+.rs-check,.rs-sr:focus-visible+.rs-radio-dot,.rs-sr:focus-visible+.rs-switch{outline:1.5px solid var(--text);outline-offset:2px}

/* ── Type scale ──
   Hierarchy from weight, color, and position; never all caps.
   --text-scale (Appearance → Text size) multiplies reading type only. */
.rs-t-xl{font-size:calc(clamp(34px,5vw,52px) * var(--text-scale, 1));font-weight:600;letter-spacing:-.035em;line-height:1.05;color:var(--text);margin:0;text-wrap:balance}
.rs-t-display{font-size:calc(38px * var(--text-scale, 1));font-weight:600;letter-spacing:-.03em;line-height:1.15;color:var(--text);margin:0;text-wrap:balance}
.rs-t-title{font-size:calc(22px * var(--text-scale, 1));font-weight:600;letter-spacing:-.02em;line-height:1.3;color:var(--text);margin:0;text-wrap:balance}
.rs-t-sub{font-size:calc(17px * var(--text-scale, 1));font-weight:500;letter-spacing:-.01em;line-height:1.5;color:var(--text-secondary);margin:0;text-wrap:pretty}
.rs-t-body{font-size:calc(15px * var(--text-scale, 1));font-weight:500;letter-spacing:-.01em;line-height:1.6;color:var(--text);margin:0;text-wrap:pretty}
.rs-t-label{font-size:calc(13px * var(--text-scale, 1));font-weight:600;letter-spacing:-.01em;line-height:1.3;color:var(--text);margin:0}

/* ── Inline code ── */
.rs-code{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:.88em;color:var(--text);background:var(--table-alt);padding:1px 5px;border-radius:var(--radius-sm);letter-spacing:0}

/* ── Buttons ── */
.rs-btn-primary{font-family:inherit;font-size:14px;font-weight:600;letter-spacing:-.01em;display:inline-flex;align-items:center;justify-content:center;gap:8px;height:40px;padding:0 22px;background:var(--text);color:var(--bg);border:1px solid transparent;border-radius:var(--radius-sm);cursor:pointer;transition:opacity var(--duration-snap) var(--ease)}
.rs-btn-primary:hover{opacity:.85}
.rs-btn-primary:disabled{opacity:.4;cursor:not-allowed}
.rs-btn-ghost{font-family:inherit;font-size:14px;font-weight:500;letter-spacing:-.01em;display:inline-flex;align-items:center;justify-content:center;gap:8px;height:40px;padding:0 22px;background:transparent;color:var(--text);border:1px solid var(--divider);border-radius:var(--radius-sm);cursor:pointer;transition:background-color var(--duration-snap) var(--ease),color var(--duration-snap) var(--ease)}
.rs-btn-ghost:hover{background:var(--divider);border-color:transparent}
.rs-btn-ghost:disabled{opacity:.4;cursor:not-allowed;background:transparent;border-color:var(--divider)}
.rs-btn-primary:focus-visible,.rs-btn-ghost:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
.rs-btn-sm{height:36px;padding:0 14px;font-size:13px;min-width:104px}

/* ── Button group: flush joined actions, one hairline between ──
   The group owns the outer stroke. Join ink is --divider (chrome
   gridline) in both schemes. A 1px gap on a divider field is the
   rule; child border:0 cannot eat it. Ghosts sit on paper. */
.rs-btn-group{
  --rs-out:var(--radius-sm);
  --rs-gap:0px;
  --rs-in:max(0px,calc(var(--rs-out) - var(--rs-gap)));
  display:inline-flex;
  align-items:stretch;
  box-sizing:border-box;
  height:40px;
  border:1px solid var(--divider);
  border-radius:var(--rs-out);
  background:var(--divider);
  gap:1px;
  overflow:hidden
}
.rs-btn-group:has(> .rs-btn-sm){height:36px}
.rs-btn-group > .rs-btn-primary,.rs-btn-group > .rs-btn-ghost{box-sizing:border-box;height:auto;border:0;border-radius:0;margin:0}
.rs-btn-group > .rs-btn-ghost{background:var(--bg)}
.rs-btn-group > .rs-btn-ghost:hover{background:var(--divider)}
.rs-btn-group > .rs-btn-ghost:disabled{background:var(--bg)}
.rs-btn-group > .rs-btn-primary{position:relative;z-index:1}

/* ── Text link: underlined by its hairline, never colored ── */
.rs-link{font-size:14px;color:var(--accent);text-decoration:none;font-weight:500;letter-spacing:-.01em;border-bottom:1px solid var(--divider);transition:border-color var(--duration-snap) var(--ease)}
.rs-link:hover{border-color:var(--accent)}
.rs-link:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
/* Gradient variant: the underline is drawn one pixel inside each end,
   so it never touches a neighbouring glyph. Hover paints it ink. */
.rs-link-underline{color:var(--text);text-decoration:none;border-bottom:none;background-image:linear-gradient(var(--divider),var(--divider));background-size:calc(100% - 1px) 1px;background-position:1px 100%;background-repeat:no-repeat;transition:background-image var(--duration-snap) var(--ease)}
.rs-link-underline:hover{background-image:linear-gradient(var(--accent),var(--accent))}

/* ── Field: quiet input: hairline border, ink focus, label above ──
   Control height matches Button (40 / --control-h). Label and hint
   sit on a 16px line-box so the 1px hairline lands on integer y.
   Gaps are 8px (4/8). */
.rs-field{width:100%;display:flex;flex-direction:column;gap:8px}
.rs-field-label{font-size:12px;font-weight:600;color:var(--text-secondary);letter-spacing:-.01em;line-height:16px}
.rs-input{
  --rs-out:var(--radius-sm);
  --rs-gap:0px;
  --rs-in:max(0px,calc(var(--rs-out) - var(--rs-gap)));
  box-sizing:border-box;
  height:var(--control-h);
  border:1px solid var(--divider);
  border-radius:var(--rs-out);
  background:var(--bg);
  color:var(--text);
  font-size:14px;
  line-height:calc(var(--control-h) - 2px);
  padding:0 10px;
  outline:none;
  font-family:inherit
}
.rs-input:focus{border-color:var(--accent)}
.rs-input-full{width:100%}
.rs-input-ok{border-color:var(--text) !important}
.rs-feedback{display:flex;align-items:center;gap:8px;font-size:12px;font-weight:500;color:var(--text-secondary);letter-spacing:-.01em;line-height:16px;margin:0;min-height:16px}
.rs-feedback-ok{color:var(--text)}
.rs-feedback svg{flex-shrink:0}
.rs-field-hint{margin:0;font-size:12px;font-weight:500;color:var(--text-secondary);letter-spacing:-.01em;line-height:16px}
.rs-field-error{margin:0;font-size:12px;font-weight:500;color:var(--text);letter-spacing:-.01em;line-height:16px}
.rs-form{display:flex;flex-direction:column;gap:16px;max-width:388px;margin:0}
.rs-label{font-size:12px;font-weight:600;color:var(--text-secondary);letter-spacing:-.01em;line-height:16px}

/* ── Input group: addon and field share one hairline.
   Outer radius is the standalone input; innerRadius with no pad. ── */
.rs-input-group{
  --rs-out:var(--radius-sm);
  --rs-gap:0px;
  --rs-in:max(0px,calc(var(--rs-out) - var(--rs-gap)));
  display:flex;
  align-items:stretch;
  box-sizing:border-box;
  width:100%;
  height:var(--control-h);
  border:1px solid var(--divider);
  border-radius:var(--rs-out);
  background:var(--bg);
  overflow:hidden
}
.rs-input-group:focus-within{border-color:var(--accent)}
.rs-input-addon{display:flex;align-items:center;padding:0 10px;font-size:13px;font-weight:500;letter-spacing:-.01em;color:var(--text-secondary);background:var(--table-alt);white-space:nowrap}
.rs-input-group > * + *{border-inline-start:1px solid var(--divider)}
.rs-input-group .rs-input{border:none;border-radius:var(--rs-in);flex:1;min-width:0;height:auto;line-height:calc(var(--control-h) - 2px)}
.rs-input-group .rs-input:focus{outline:none}
.rs-input-group-end .rs-input-addon{border-inline-start:1px solid var(--divider)}

/* ── Native select: the platform list, Raster chrome ── */
.rs-native-select{appearance:none;box-sizing:border-box;height:var(--control-h);font-family:inherit;font-size:14px;font-weight:500;letter-spacing:-.01em;line-height:calc(var(--control-h) - 2px);color:var(--text);background:var(--bg) url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 16 16' width='16' height='16' fill='none' stroke='%231A1A1A' stroke-width='1' stroke-linecap='butt' stroke-linejoin='miter'><g transform='rotate(90 8 8)'><path d='M5.5 3.5 L10.5 8 L5.5 12.5' vector-effect='non-scaling-stroke'/></g></svg>") no-repeat right 10px center;border:1px solid var(--divider);border-radius:var(--radius-sm);padding:0 32px 0 10px;outline:none;width:100%}
.rs-native-select:focus{border-color:var(--accent)}
[data-theme="dark"] .rs-native-select{background-image:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 16 16' width='16' height='16' fill='none' stroke='%23E8E8E8' stroke-width='1' stroke-linecap='butt' stroke-linejoin='miter'><g transform='rotate(90 8 8)'><path d='M5.5 3.5 L10.5 8 L5.5 12.5' vector-effect='non-scaling-stroke'/></g></svg>")}

/* ── Inline form: the action lives inside the field ── */
.rs-inline-field{
  --rs-out:var(--radius-sm);
  --rs-gap:4px;
  --rs-in:max(0px,calc(var(--rs-out) - var(--rs-gap)));
  display:flex;
  align-items:center;
  gap:8px;
  width:100%;
  border:1px solid var(--divider);
  border-radius:var(--rs-out);
  background:var(--bg);
  padding:var(--rs-gap) 6px var(--rs-gap) 12px;
  transition:border-color var(--duration-snap) var(--ease)
}
.rs-inline-field:focus-within{border-color:var(--accent)}
.rs-inline-input{flex:1;min-width:0;border:none;background:none;font-family:inherit;font-size:14px;letter-spacing:-.01em;color:var(--text);outline:none;padding:7px 0}
.rs-inline-input::placeholder{color:var(--text-secondary)}
.rs-inline-btn{height:28px;padding:0 16px;font-size:12.5px;min-width:0;border-radius:var(--rs-in);white-space:nowrap}
.rs-reveal{max-width:0;opacity:0;overflow:hidden;transition:max-width var(--duration) var(--ease),opacity var(--duration) var(--ease)}
.rs-reveal-in{max-width:160px;opacity:1}
.rs-subscribed{display:flex;align-items:center;gap:8px;font-size:14px;font-weight:600;letter-spacing:-.01em;color:var(--text);animation:rsConfirm var(--duration-confirm) var(--ease)}
@keyframes rsConfirm{from{opacity:0}to{opacity:1}}

/* ── Radio: the dot is ink, never a hue ── */
.rs-radio{display:flex;align-items:center;gap:9px;font-size:14px;color:var(--text);letter-spacing:-.01em}
.rs-radio-dot{width:16px;height:16px;border-radius:50%;border:1.5px solid var(--divider);position:relative;flex-shrink:0}
.rs-radio-on{border-color:var(--text)}
.rs-radio-on::after{content:'';position:absolute;inset:3px;border-radius:50%;background:var(--text)}

/* ── Checkbox: 16px boxes, 3px radius, ink when checked ── */
.rs-choice{display:flex;align-items:center;gap:9px;font-size:14px;color:var(--text);letter-spacing:-.01em}
.rs-check{width:16px;height:16px;border-radius:3px;border:1.5px solid var(--divider);flex-shrink:0;display:flex;align-items:center;justify-content:center;color:var(--bg)}
.rs-check svg{width:12px;height:12px}
.rs-check-on{background:var(--text);border-color:var(--text)}

/* ── Switch: state moves, layout doesn't ── */
.rs-switch{display:inline-flex;box-sizing:border-box;width:32px;height:18px;border-radius:9px;border:1.5px solid var(--divider);position:relative;flex-shrink:0;transition:background-color var(--duration) var(--ease),border-color var(--duration) var(--ease)}
.rs-switch i{position:absolute;top:1.5px;left:1.5px;width:12px;height:12px;border-radius:50%;background:var(--text-secondary);transition:transform var(--duration) var(--ease)}
.rs-switch-on{background:var(--text);border-color:var(--text)}
.rs-switch-on i{background:var(--bg);transform:translateX(14px)}
button.rs-switch{padding:0;background:none;cursor:pointer;border:1.5px solid var(--divider)}
button.rs-switch.rs-switch-on{background:var(--text);border-color:var(--text)}

/* ── Slider: thin track with ink fill and 14px thumb ── */
.rs-slider{position:relative;height:2px;background:var(--divider);border-radius:1px;margin:10px 0}
.rs-slider-fill{position:absolute;left:0;top:0;bottom:0;background:var(--text);border-radius:1px}
.rs-slider-thumb{position:absolute;top:50%;transform:translate(-50%,-50%);width:14px;height:14px;border-radius:50%;background:var(--bg);border:1.5px solid var(--text)}
.rs-slider input[type=range]{position:absolute;left:0;right:0;top:-8px;bottom:-8px;width:100%;height:auto;opacity:0;cursor:pointer;margin:0}
.rs-slider:has(input[type=range]:focus-visible) .rs-slider-thumb{outline:1.5px solid var(--text);outline-offset:2px}

/* ── Progress: the percentage lives in the label, never in the bar ── */
.rs-progress-head{display:flex;justify-content:space-between;font-size:12px;font-weight:500;color:var(--text-secondary);letter-spacing:-.01em;margin-bottom:7px}
.rs-progress{height:4px;background:var(--divider-subtle);border-radius:2px;overflow:hidden}
.rs-progress span{display:block;height:100%;background:var(--text);border-radius:2px}

/* ── Tabs: one line of type. Hairline on the active tab only. ── */
.rs-tabs{display:flex;align-items:baseline;gap:22px;max-width:360px;border:none;box-shadow:none;background:none}
.rs-tab,
button.rs-tab{
  -webkit-appearance:none;
  appearance:none;
  padding:8px 0;
  font-size:14px;
  font-family:inherit;
  color:var(--text-secondary);
  letter-spacing:-.01em;
  text-decoration:none;
  background:none;
  background-image:none;
  box-shadow:none;
  border:none;
  border-radius:0;
  cursor:pointer;
  text-align:left;
}
.rs-tab-active,
button.rs-tab.rs-tab-active{
  color:var(--text);
  font-weight:600;
  border:none;
  box-shadow:inset 0 -1px 0 var(--text);
}

/* ── Breadcrumbs: one ink trail. Slashes at 40%. Current page is full ink.
   Ancestors stay Inter/ink — never a UA :link or :visited color, never an accent. ── */
.rs-crumbs{font-size:13px;color:var(--text);letter-spacing:-.01em;display:flex;align-items:baseline;gap:8px}
.rs-crumbs a,
.rs-crumbs a:link,
.rs-crumbs a:visited,
.rs-crumbs a:hover,
.rs-crumbs a:active,
.rs-crumbs a:focus,
.rs-crumbs a:focus-visible,
.rs-crumbs a:any-link,
.rs-crumbs a:-webkit-any-link,
.rs-crumbs .rs-crumbs-link{
  color:var(--text);
  text-decoration:none;
  background:none;
}
.rs-crumbs a,
.rs-crumbs a:link,
.rs-crumbs a:visited,
.rs-crumbs a:any-link,
.rs-crumbs a:-webkit-any-link,
.rs-crumbs .rs-crumbs-link{opacity:.55}
.rs-crumbs a:hover,.rs-crumbs a:focus-visible{opacity:1}
.rs-crumbs-sep{color:var(--text);opacity:.4}
.rs-crumbs-here{color:var(--text);opacity:1}

/* ── Crumb bar: fixed top bar in the house chrome ──
   Transparent at rest; once the page cover scrolls away it gains the
   paper background and its bottom hairline, and the breadcrumbs
   appear. From 900px the root crumb holds the TOC column; the inner row
   starts one module in at the 1024px rail. */
.rs-crumb-bar{position:fixed;top:0;left:0;right:0;z-index:160;display:flex;align-items:center;height:72px;font-size:13px;font-weight:500;letter-spacing:-.01em;line-height:1.3;background:none;border-bottom:1px solid transparent;transition:var(--transition)}
.rs-crumb-bar-scrolled{background:var(--bg);border-bottom-color:var(--divider)}
.rs-crumb-bar-inner{display:flex;align-items:center;gap:20px;width:100%;min-width:0;padding:0 56px 0 76px}
.rs-crumb-bar .rs-crumbs{margin:0;min-width:0;overflow:hidden;white-space:nowrap;opacity:0;pointer-events:none;transition:opacity var(--duration) var(--ease)}
.rs-crumb-bar-scrolled .rs-crumbs{opacity:1;pointer-events:auto}
.rs-crumb-bar a{color:inherit;text-decoration:none}
.rs-crumb-root{flex-shrink:0;color:var(--text);text-decoration:none;transition:color var(--duration-snap) var(--ease)}
.rs-crumb-bar .rs-crumbs-here{overflow:hidden;text-overflow:ellipsis}
/* Root abbreviation: the short name shows only on phones, leaving the
   path room to dock and ellipsize. */
.rs-crumb-root-short{display:none}
@media(min-width:900px){.rs-crumb-root{width:184px}}
@media(min-width:1024px){.rs-crumb-bar-inner{margin-left:204px;padding-left:var(--pad)}}
@media(max-width:899px){.rs-crumb-bar-inner{gap:6px}.rs-crumb-root{font-weight:600}}
@media(max-width:640px){
  .rs-crumb-bar{height:64px;font-size:12px}
  .rs-crumb-bar-inner{padding:0 50px 0 62px}
  .rs-crumb-root-full{display:none}
  .rs-crumb-root-short{display:inline}
}
@media(max-width:480px){.rs-crumb-bar-inner{padding:0 56px 0 74px}}

/* ── Pagination: squares, not pills ── */
.rs-pages{display:flex;align-items:center;gap:5px}
.rs-page{width:26px;height:26px;border-radius:var(--radius-sm);display:flex;align-items:center;justify-content:center;font-size:13px;color:var(--text-secondary);border:1px solid transparent}
.rs-page .rs-icon{display:block;color:inherit}
.rs-page:not(.rs-page-gap):not(.rs-page-on){border-color:var(--divider)}
.rs-page.rs-page-on,button.rs-page-on{background:var(--text);color:var(--bg);font-weight:600}
button.rs-page{padding:0;background:none;font-family:inherit;cursor:pointer}

/* ── Dropdown + menu: the menu overlays, it never pushes layout ── */
.rs-select{position:relative;display:inline-block;min-width:180px}
.rs-select .rs-menu{position:absolute;top:100%;left:0;right:0;z-index:50;margin-top:6px}
.rs-dropdown{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:9px 12px;border:1px solid var(--divider);border-radius:var(--radius-sm);font-size:14px;color:var(--text);letter-spacing:-.01em}
button.rs-dropdown{cursor:pointer;font-family:inherit;background:none;width:100%}
.rs-menu{
  --rs-out:var(--radius-sm);
  --rs-gap:0px;
  --rs-in:max(0px,calc(var(--rs-out) - var(--rs-gap)));
  border:1px solid var(--divider);
  border-radius:var(--rs-out);
  margin-top:6px;
  overflow:hidden;
  background:var(--bg);
  box-shadow:0 8px 24px rgba(0,0,0,0.06)
}
.rs-menu:has(.rs-cal){
  --rs-gap:12px;
  padding:var(--rs-gap)
}
.rs-menu-item{display:block;padding:9px 12px;font-size:14px;color:var(--text);letter-spacing:-.01em;border-bottom:1px solid var(--divider)}
.rs-menu-item:last-child{border-bottom:none}
.rs-menu-item.rs-menu-item-active,button.rs-menu-item-active{background:var(--divider-subtle)}
button.rs-menu-item{width:100%;text-align:left;cursor:pointer;background:none;border-left:none;border-right:none;border-top:none;font-family:inherit}

/* ── Dialog: one question, two equal actions, no third option.
   Nested actions use Steve’s innerRadius of the frame. ── */
.rs-dialog{
  --rs-out:var(--radius-sm);
  --rs-gap:20px;
  --rs-in:max(0px,calc(var(--rs-out) - var(--rs-gap)));
  max-width:320px;
  border:1px solid var(--divider);
  border-radius:var(--rs-out);
  padding:var(--rs-gap);
  background:var(--bg);
  box-shadow:none
}
dialog.rs-dialog{color:var(--text)}
dialog.rs-dialog::backdrop{background:rgba(0,0,0,0.25)}
.rs-dialog-title{display:block;font-size:15px;font-weight:600;letter-spacing:-.01em;color:var(--text);margin-bottom:6px}
.rs-dialog-body{font-size:13.5px;color:var(--text-secondary);letter-spacing:-.01em;line-height:1.55;margin:0 0 16px}
.rs-dialog-actions{display:flex;justify-content:flex-end;gap:8px}
.rs-dialog .rs-btn-primary,.rs-dialog .rs-btn-ghost{border-radius:var(--rs-in)}

/* ── Badges: outline for recommendations, solid for done, muted for pending ── */
.rs-badge{font-size:11px;font-weight:600;letter-spacing:.02em;color:var(--accent);border:1px solid var(--accent);padding:3px 10px;line-height:1.4;border-radius:var(--radius-sm)}
.rs-badge-solid{font-size:11px;font-weight:600;letter-spacing:.02em;color:var(--bg);background:var(--text);padding:4px 11px;line-height:1.4;border-radius:var(--radius-sm)}
.rs-badge-muted{font-size:11px;font-weight:600;letter-spacing:.02em;color:var(--text-secondary);background:var(--divider-subtle);padding:4px 11px;line-height:1.4;border-radius:var(--radius-sm)}

/* ── Mono chip: technical identifiers ── */
.rs-chip{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:11px;font-weight:500;color:var(--text-secondary);border:1px solid color-mix(in srgb,currentColor 35%,transparent);padding:3px 7px;line-height:1;border-radius:var(--radius-sm)}

/* ── Card: typography stack. No outline. Chrome-square. ── */
.rs-card{
  --rs-out:0;
  --rs-gap:20px;
  --rs-in:max(0px,calc(var(--rs-out) - var(--rs-gap)));
  border:0;
  border-radius:var(--rs-out);
  padding:0;
  max-width:360px;
  background:none;
  box-shadow:none
}
.rs-card-label{font-size:12px;font-weight:600;color:var(--accent);letter-spacing:-.01em;display:block;margin-bottom:6px}
.rs-card-title{font-size:17px;font-weight:600;color:var(--text);letter-spacing:-.02em;margin:0 0 8px}
.rs-card-body{font-size:14px;color:var(--text-secondary);font-weight:500;letter-spacing:-.01em;line-height:1.6;margin:0}
.rs-card-in{
  box-sizing:border-box;
  border:0;
  border-radius:var(--rs-in);
  min-height:0;
  padding:0;
  background:none
}
.rs-card .rs-btn-primary,.rs-card .rs-btn-ghost,.rs-card .rs-input,.rs-card .rs-textarea{border-radius:var(--rs-in)}
.rs-card .rs-btn-group{--rs-out:var(--rs-in);border-radius:var(--rs-out)}

/* ── Concentric radius: Steve Ruiz innerRadius, clamped at 0.
   --rs-in is the closed form of the circular-corner fit.
   Do not reassign --rs-out on the inner frame: that cycles the custom
   property and the used radius becomes 0. ── */
.rs-nest{
  --rs-out:var(--radius-sm);
  --rs-gap:var(--pad);
  --rs-in:max(0px,calc(var(--rs-out) - var(--rs-gap)));
  box-sizing:border-box;
  border:1px solid var(--divider);
  border-radius:var(--rs-out);
  padding:var(--rs-gap);
  background:var(--bg);
}
.rs-nest-in{
  box-sizing:border-box;
  border:1px solid var(--divider);
  border-radius:var(--rs-in);
  min-height:72px;
  background:var(--bg);
  display:flex;
  align-items:flex-end
}
.rs-nest .rs-btn-primary,.rs-nest .rs-btn-ghost{border-radius:var(--rs-in)}

/* ── Stepper: numbered dots joined by hairlines that meet the marks ── */
.rs-steps{display:flex;align-items:flex-start;width:100%;max-width:100%;gap:0}
.rs-step{position:relative;display:flex;flex-direction:column;align-items:flex-start;gap:3px;flex:1 1 0;min-width:0}
.rs-step-dot{width:24px;height:24px;border-radius:50%;border:1.5px solid var(--divider);display:flex;align-items:center;justify-content:center;font-size:11px;font-weight:600;color:var(--text-secondary);margin-bottom:6px;background:var(--bg);position:relative;z-index:1}
.rs-step-done{background:var(--text);border-color:var(--text);color:var(--bg)}
.rs-step-active{border-color:var(--text);color:var(--text)}
.rs-step-name{font-size:13px;font-weight:600;letter-spacing:-.01em;color:var(--text);line-height:1.2}
.rs-step-sub{font-size:11px;font-weight:500;color:var(--text-secondary);letter-spacing:-.01em}
.rs-step-line{position:absolute;top:11.5px;left:24px;right:0;height:1px;background:var(--divider);margin:0;min-width:0;z-index:0}

/* ── Table: hairline rows on the open grid; no cell borders ──
   Scoped to .rs-table so linking raster.css never restyles a table
   it doesn't own. The compat layer re-emits these on bare elements. */
.rs-table{width:calc(100% + 40px);border-collapse:collapse;margin:16px 0 24px -20px;font-size:14px}
.rs-table th{text-align:left;font-weight:600;color:var(--text);letter-spacing:-.01em;padding:10px 16px 10px 12px;border-bottom:2px solid var(--divider);font-size:13px}
.rs-table th:first-child{padding-left:20px}
.rs-table th:last-child{padding-right:20px}
.rs-table td{padding:10px 16px 10px 12px;color:var(--text-secondary);font-weight:500;letter-spacing:-.01em;border-bottom:1px solid var(--divider);vertical-align:top}
.rs-table td:first-child{padding-left:20px}
.rs-table td:last-child{padding-right:20px}
.rs-table tr:nth-child(even) td{background:var(--table-alt)}
.rs-table td:last-child,.rs-table th:last-child{text-align:right}
.rs-table tr.rs-total-row td{font-weight:500;color:var(--text);border-top:2px solid var(--divider);border-bottom:2px solid var(--divider)}
@media(max-width:640px){
  .rs-table{font-size:12px;width:calc(100% + 2*var(--pad));margin-left:calc(-1*var(--pad));margin-right:calc(-1*var(--pad))}
  .rs-table th{padding:8px 10px;font-size:12px}
  .rs-table td{padding:8px 10px}
  .rs-table th:first-child,.rs-table td:first-child{padding-left:var(--pad)}
  .rs-table th:last-child,.rs-table td:last-child{padding-right:var(--pad)}
}

/* ── Icons: 16 viewBox, 1px currentColor hairline. Size from the svg width. ── */
.rs-icons{display:flex;gap:18px;align-items:center;color:var(--text)}
.rs-icon{display:block;flex-shrink:0;overflow:visible;color:inherit}
.rs-btn-primary .rs-icon,.rs-btn-ghost .rs-icon,.rs-toggle .rs-icon{display:block;flex-shrink:0}
.rs-icons svg{flex-shrink:0}
.rs-icons svg:not([width]){width:16px;height:16px}
.rs-icon-catalog{width:100%;display:flex;flex-direction:column;gap:28px;text-align:left;align-self:stretch}
.rs-icon-group{display:flex;flex-direction:column;gap:12px}
.rs-icon-group-title{margin:0;font-size:12px;font-weight:600;letter-spacing:0;color:var(--text-secondary);text-transform:none}
.rs-icon-grid{display:grid;grid-template-columns:repeat(auto-fill,184px);column-gap:var(--gutter);row-gap:20px;justify-content:start;width:100%}
.rs-icon-cell{display:flex;flex-direction:column;align-items:flex-start;gap:8px;width:184px}
.rs-icon-pair{display:flex;align-items:center;gap:16px;min-height:24px}
.rs-icon-kin{display:flex;align-items:center;gap:8px;min-height:24px}
.rs-icon-label{font-size:11px;line-height:1.3;color:var(--text-secondary);text-transform:none}
@media(max-width:480px){
  .rs-icon-grid{grid-template-columns:minmax(0,1fr)}
  .rs-icon-cell{width:100%}
}

/* ── Accordion: native <details>; one open at a time via the name attribute ── */
.rs-acc{border-top:1px solid var(--divider)}
.rs-acc-item{border-bottom:1px solid var(--divider)}
.rs-acc-item summary{list-style:none;cursor:pointer;display:flex;justify-content:space-between;align-items:center;gap:12px;padding:14px 0;font-size:14.5px;font-weight:600;letter-spacing:-.01em;color:var(--text)}
.rs-acc-item summary::-webkit-details-marker{display:none}
.rs-acc-chevron{flex-shrink:0;color:var(--text-secondary);transition:transform var(--duration) var(--ease)}
.rs-acc-item[open] .rs-acc-chevron{transform:rotate(180deg)}
.rs-acc-body{padding:0 0 16px;font-size:13.5px;line-height:1.6;color:var(--text-secondary)}

/* ── Alert: a hairline frame; emphasis from weight, never a hue ── */
.rs-alert{display:flex;gap:10px;border:1px solid var(--divider);border-radius:var(--radius);padding:12px 14px;align-items:flex-start}
.rs-alert svg{flex-shrink:0;margin-top:1px;color:var(--text)}
.rs-alert-title{display:block;font-size:13.5px;font-weight:600;letter-spacing:-.01em;color:var(--text)}
.rs-alert-body{font-size:13px;line-height:1.55;letter-spacing:-.01em;color:var(--text-secondary);margin:2px 0 0}
.rs-alert-solid{background:var(--text);border-color:var(--text)}
.rs-alert-solid svg,.rs-alert-solid .rs-alert-title{color:var(--bg)}
.rs-alert-solid .rs-alert-body{color:var(--bg);opacity:.75}

/* ── Avatar: initials in a quiet circle; images cover ── */
.rs-avatar{width:32px;height:32px;border-radius:50%;background:var(--divider-subtle);color:var(--text);display:inline-flex;align-items:center;justify-content:center;font-size:12px;font-weight:600;letter-spacing:-.01em;overflow:hidden;flex-shrink:0;user-select:none}
.rs-avatar img{width:100%;height:100%;object-fit:cover}
.rs-avatar-sm{width:24px;height:24px;font-size:10px}
.rs-avatar-lg{width:48px;height:48px;font-size:16px}
.rs-avatar-row{display:flex}
.rs-avatar-row .rs-avatar{border:2px solid var(--bg);margin-left:-8px}
.rs-avatar-row .rs-avatar:first-child{margin-left:0}

/* ── Item: a flush row. Title, note, trailing meta ── */
.rs-item{display:flex;align-items:center;justify-content:space-between;gap:16px;min-height:48px;padding:10px 0;border-bottom:1px solid var(--divider);border-radius:0}
.rs-item:last-child{border-bottom:none}
.rs-item-title{margin:0;font-size:14px;font-weight:600;letter-spacing:-.01em;color:var(--text)}
.rs-item-desc{margin:2px 0 0;font-size:12.5px;font-weight:500;letter-spacing:-.01em;color:var(--text-secondary)}
.rs-item-meta{font-size:12px;font-weight:500;letter-spacing:-.01em;color:var(--text-secondary);flex-shrink:0}

/* ── Textarea: the quiet field, taller ── */
.rs-textarea{border:1px solid var(--divider);border-radius:var(--radius-sm);background:var(--bg);color:var(--text);font-size:14px;line-height:1.55;padding:8px 10px;outline:none;font-family:inherit;min-height:96px;resize:vertical;width:100%}
.rs-textarea:focus{border-color:var(--accent)}
.rs-textarea::placeholder{color:var(--text-secondary)}

/* ── Separator: a hairline, horizontal or vertical.
   Chrome uses --divider (the stronger of the two grid inks).
   The page 204 uses --grid-line. Same family, two steps. */
.rs-sep{border:none;border-top:1px solid var(--divider);margin:20px 0}
.rs-sep-v{display:inline-block;width:1px;align-self:stretch;background:var(--divider);margin:0 12px}

/* ── Skeleton: a quiet pulse; still under reduced motion ── */
.rs-skeleton{display:block;background:var(--divider-subtle);border-radius:var(--radius-sm);animation:rsSkel 1.6s ease-in-out infinite}
@keyframes rsSkel{0%,100%{opacity:1}50%{opacity:.55}}
@media(prefers-reduced-motion:reduce){.rs-skeleton{animation:none}}

/* ── Empty: a quiet vacant cell, not an illustration ── */
.rs-empty{display:flex;flex-direction:column;justify-content:center;gap:8px;min-height:204px;padding:20px;border:1px solid var(--divider);border-radius:0}
.rs-empty-title{margin:0;font-size:15px;font-weight:600;letter-spacing:-.01em;color:var(--text)}
.rs-empty-body{margin:0;font-size:13.5px;line-height:1.55;letter-spacing:-.01em;color:var(--text-secondary)}
.rs-empty-action{margin-top:8px;width:fit-content}

/* ── Spinner: 1px currentColor hairline ring. Raster icon law. ── */
.rs-spinner{display:inline-flex;width:16px;height:16px;color:var(--text);vertical-align:middle}
.rs-spinner svg{display:block;width:16px;height:16px;animation:rs-spin .7s linear infinite}
@keyframes rs-spin{to{transform:rotate(360deg)}}

/* ── Tooltip: CSS-only, shows on hover and keyboard focus alike ── */
.rs-tip{position:relative;display:inline-flex}
.rs-tip::after{content:attr(data-tip);position:absolute;bottom:calc(100% + 8px);left:50%;transform:translateX(-50%);background:var(--text);color:var(--bg);font-size:11.5px;font-weight:500;letter-spacing:-.01em;line-height:1.3;padding:5px 9px;border-radius:var(--radius-sm);white-space:nowrap;opacity:0;pointer-events:none;z-index:180;transition:opacity var(--duration-snap) var(--ease) var(--duration-snap)}
.rs-tip:hover::after,.rs-tip:focus-within::after{opacity:1}
@media(prefers-reduced-motion:reduce){.rs-tip::after{transition:opacity var(--duration-snap) var(--ease) var(--duration-snap)}}

/* ── Toast: quiet confirmations, bottom right, announced politely ── */
.rs-toasts{position:fixed;bottom:20px;right:20px;z-index:300;display:flex;flex-direction:column;align-items:flex-end;gap:8px}
.rs-toast{display:flex;align-items:flex-start;gap:10px;background:var(--bg);border:1px solid var(--divider);border-radius:var(--radius);box-shadow:0 8px 24px rgba(0,0,0,0.06);padding:10px 14px;max-width:340px;animation:rsToastIn var(--duration-confirm) var(--ease)}
.rs-toast-title{display:block;font-size:13px;font-weight:600;letter-spacing:-.01em;color:var(--text)}
.rs-toast-body{font-size:12.5px;line-height:1.5;letter-spacing:-.01em;color:var(--text-secondary);margin:1px 0 0}
@keyframes rsToastIn{from{opacity:0}to{opacity:1}}
@media(prefers-reduced-motion:reduce){.rs-toast{animation:none}}

/* ── Menu separators: for action menus ── */
.rs-menu-sep{border:none;border-top:1px solid var(--divider);margin:4px 0}

/* ── Toggle: a press switch; on is ink, like everything on ── */
.rs-toggle{display:inline-flex;align-items:center;justify-content:center;gap:6px;height:32px;min-width:32px;padding:0 10px;font-size:13px;font-weight:500;letter-spacing:-.01em;background:none;border:1px solid var(--divider);border-radius:var(--radius-sm);color:var(--text-secondary);cursor:pointer;font-family:inherit;transition:background-color var(--duration-snap) var(--ease),color var(--duration-snap) var(--ease),border-color var(--duration-snap) var(--ease)}
.rs-toggle[aria-pressed="true"]{background:var(--text);border-color:var(--text);color:var(--bg)}
.rs-toggle-group{
  --rs-out:var(--radius-sm);
  --rs-gap:0px;
  --rs-in:max(0px,calc(var(--rs-out) - var(--rs-gap)));
  display:inline-flex;
  align-items:stretch;
  box-sizing:border-box;
  height:32px;
  border:1px solid var(--divider);
  border-radius:var(--rs-out);
  overflow:hidden
}
.rs-toggle-group .rs-toggle{height:auto;border:0;border-radius:0;margin:0}
.rs-toggle-group .rs-toggle + .rs-toggle{border-inline-start:1px solid var(--divider)}
.rs-toggle-group .rs-toggle[aria-pressed="true"]{position:relative;z-index:1}

/* ── Popover: the native Popover API: top layer, light dismiss ── */
.rs-popover{position:fixed;inset:auto;margin:0;border:1px solid var(--divider);border-radius:var(--radius);background:var(--bg);color:var(--text);box-shadow:0 8px 24px rgba(0,0,0,0.06);padding:14px;width:240px;font-size:13px;line-height:1.55;letter-spacing:-.01em}
.rs-popover-title{display:block;font-size:13px;font-weight:600;letter-spacing:-.01em;color:var(--text);margin-bottom:4px}
.rs-popover-body{color:var(--text-secondary);margin:0}

/* ── Sheet: a native <dialog> parked at the edge ── */
dialog.rs-sheet{position:fixed;inset:0 0 0 auto;margin:0;height:100dvh;max-height:none;width:360px;max-width:85vw;border:none;border-left:1px solid var(--divider);border-radius:var(--radius-sm) 0 0 var(--radius-sm);padding:24px 20px;background:var(--bg);color:var(--text);box-shadow:none}
dialog.rs-sheet::backdrop{background:rgba(0,0,0,0.25)}
dialog.rs-sheet-left{inset:0 auto 0 0;border-left:none;border-right:1px solid var(--divider);border-radius:0 var(--radius-sm) var(--radius-sm) 0;box-shadow:none}
.rs-sheet-title{display:block;font-size:15px;font-weight:600;letter-spacing:-.01em;color:var(--text);margin-bottom:6px}
.rs-sheet-body{font-size:13.5px;line-height:1.6;letter-spacing:-.01em;color:var(--text-secondary);margin:0}

/* ── Drawer: a native <dialog> from the bottom edge. No shadow. ── */
dialog.rs-drawer{position:fixed;inset:auto 0 0 0;margin:0;width:100%;max-width:none;height:auto;max-height:85dvh;border:none;border-top:1px solid var(--divider);border-radius:var(--radius-sm) var(--radius-sm) 0 0;padding:24px 20px;background:var(--bg);color:var(--text);box-shadow:none}
dialog.rs-drawer::backdrop{background:rgba(0,0,0,0.25)}
.rs-drawer-title{display:block;font-size:15px;font-weight:600;letter-spacing:-.01em;color:var(--text);margin-bottom:6px}
.rs-drawer-body{font-size:13.5px;line-height:1.6;letter-spacing:-.01em;color:var(--text-secondary);margin:0}

/* ── Scroll area: quiet scroll with feathered edges, no scrollbar chrome ── */
.rs-scroll{overflow-y:auto;scrollbar-width:none;-webkit-mask-image:linear-gradient(to bottom,transparent 0,#000 20px,#000 calc(100% - 20px),transparent 100%);mask-image:linear-gradient(to bottom,transparent 0,#000 20px,#000 calc(100% - 20px),transparent 100%);padding:12px 0}
.rs-scroll::-webkit-scrollbar{display:none}

/* ── Charts: a poster field. Hairline grid, ink marks, no radius, no shadow.
   Chrome is monochrome. A field may set --rs-chart-spot (one Crouwel color).
   Series otherwise differ by texture, never a rainbow. ── */
.rs-chart{position:relative;width:100%;border-radius:0;box-shadow:none}
.rs-chart svg{display:block;width:100%;height:auto;overflow:visible}
.rs-chart-field{
  --rs-chart-spot:var(--text);
  isolation:isolate;
  background:var(--bg);
  border:1px solid var(--divider);
  border-radius:0;
  box-shadow:none;
  padding:16px;
}
.rs-chart-head{display:flex;justify-content:space-between;align-items:baseline;gap:12px;margin-bottom:10px}
.rs-chart-title{font-size:13px;font-weight:600;letter-spacing:-.01em;color:var(--text)}
.rs-chart-value{font-size:20px;font-weight:600;letter-spacing:-.02em;color:var(--text);font-variant-numeric:tabular-nums}
.rs-chart-grid{stroke:var(--divider);stroke-width:1}
.rs-chart-baseline{stroke:var(--divider);stroke-width:1}
.rs-chart-axis{fill:var(--text-secondary);font-size:11px;font-weight:500;letter-spacing:0;font-variant-numeric:tabular-nums}
.rs-chart-line{fill:none;stroke:var(--text);stroke-width:1;stroke-linecap:butt;stroke-linejoin:miter}
.rs-chart-line-dashed{stroke-dasharray:4 4}
.rs-chart-line-muted{stroke:var(--text-secondary)}
.rs-chart-line-dotted{stroke:var(--text-secondary);stroke-dasharray:0.1 5;stroke-width:1.5;stroke-linecap:butt}
.rs-chart-line-spot{stroke:var(--rs-chart-spot)}
.rs-chart-area{fill:var(--text);opacity:.08;stroke:none}
.rs-chart-area-spot{fill:var(--rs-chart-spot);opacity:.16;stroke:none}
.rs-chart-bar{fill:var(--text)}
.rs-chart-bar-muted{fill:var(--divider)}
.rs-chart-bar-spot{fill:var(--rs-chart-spot)}
.rs-chart-cursor{stroke:var(--divider);stroke-width:1}
.rs-chart-dot{fill:var(--bg);stroke:var(--text);stroke-width:1}
.rs-chart-mark{fill:var(--text)}
.rs-chart-mark-spot{fill:var(--rs-chart-spot)}
.rs-chart-ann{fill:var(--text-secondary);font-size:11px;font-weight:500;letter-spacing:-.01em}
.rs-chart-tip{
  position:absolute;pointer-events:none;
  background:var(--bg);border:1px solid var(--divider);
  border-radius:0;box-shadow:none;
  padding:6px 8px;font-size:12px;letter-spacing:-.01em;color:var(--text);
  white-space:nowrap;z-index:60;transform:translate(-50%,calc(-100% - 8px));
}
.rs-chart-tip-label{display:block;font-size:11px;color:var(--text-secondary);margin-bottom:2px}
.rs-chart-tip-row{display:flex;align-items:center;justify-content:space-between;gap:10px}
.rs-chart-tip-name{color:var(--text-secondary)}
.rs-chart-tip-val{font-weight:600;font-variant-numeric:tabular-nums}
.rs-chart-legend{display:flex;flex-wrap:wrap;gap:14px;margin-top:10px}
.rs-chart-legend-item{display:flex;align-items:center;gap:7px;font-size:12px;font-weight:500;letter-spacing:-.01em;color:var(--text-secondary)}
.rs-chart-legend-item svg{display:block}
.rs-chart-share{display:flex;height:8px;width:100%;border:1px solid var(--divider);border-radius:0}
.rs-chart-share-seg{height:100%;background:var(--text)}
.rs-chart-share-seg:nth-child(2){background:var(--text-secondary)}
.rs-chart-share-seg:nth-child(3){background:var(--divider)}
.rs-chart-share-seg-spot{background:var(--rs-chart-spot)}
.rs-chart-hist{fill:var(--divider);stroke:none}
.rs-chart-donut{display:block}
.rs-chart-donut-track{fill:none;stroke:var(--divider);stroke-width:1}
.rs-chart-donut-value{fill:none;stroke:var(--rs-chart-spot);stroke-width:1;stroke-linecap:butt}
.rs-chart-donut-label{fill:var(--text);font-size:12px;font-weight:500;letter-spacing:-.03em;font-variant-numeric:tabular-nums}
.rs-chart-donut-caption{fill:var(--text-secondary);font-size:8px;font-weight:500;letter-spacing:.06em}
.rs-chart-multi{display:grid;grid-template-columns:repeat(auto-fill,minmax(184px,1fr));gap:20px}
.rs-chart-multi-cap{margin:0 0 8px;font-size:12px;font-weight:600;letter-spacing:-.01em;color:var(--text)}
.rs-chart-multi .rs-chart-field{padding:12px}
.rs-spark{--rs-chart-spot:var(--text);display:inline-block;vertical-align:middle}
.rs-spark svg{display:block;overflow:visible}
.rs-spark .rs-chart-line{stroke-width:1}
.rs-chart-plot{transform-origin:center}
.rs-chart-bar,.rs-chart-mark,.rs-chart-share-seg{transition:fill var(--duration-snap) var(--ease),opacity var(--duration-snap) var(--ease)}

/* ── Collapsible: a bare <details>, no chrome ── */
.rs-disclosure summary{list-style:none;cursor:pointer;display:inline-flex;align-items:center;gap:7px;font-size:13.5px;font-weight:600;letter-spacing:-.01em;color:var(--text)}
.rs-disclosure summary::-webkit-details-marker{display:none}
.rs-disclosure .rs-acc-chevron{transition:transform var(--duration) var(--ease)}
.rs-disclosure[open] .rs-acc-chevron{transform:rotate(180deg)}
.rs-disclosure-body{padding:10px 0 0;font-size:13.5px;line-height:1.6;color:var(--text-secondary)}

/* ── Hover card: rich preview on hover or keyboard focus ── */
.rs-hover-card{position:relative;display:inline-block}
.rs-hover-card-panel{position:absolute;top:calc(100% + 8px);left:0;z-index:170;width:260px;background:var(--bg);border:1px solid var(--divider);border-radius:var(--radius);box-shadow:0 8px 24px rgba(0,0,0,0.06);padding:14px;font-size:13px;line-height:1.55;letter-spacing:-.01em;color:var(--text-secondary);opacity:0;visibility:hidden;transition:opacity var(--duration-snap) var(--ease) var(--duration-snap),visibility var(--duration-snap) var(--ease) var(--duration-snap)}
.rs-hover-card:hover .rs-hover-card-panel,.rs-hover-card:focus-within .rs-hover-card-panel{opacity:1;visibility:visible}

/* ── Kbd: keys in the mono stack with a pressed bottom edge ── */
.rs-kbd{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:11px;font-weight:500;color:var(--text-secondary);background:var(--bg);border:1px solid var(--divider);border-bottom-width:2px;border-radius:var(--radius-sm);padding:2px 6px;line-height:1.2}
.rs-kbd-pair{display:inline-flex;align-items:stretch;margin-inline-start:10px;vertical-align:middle}
.rs-kbd-pair .rs-kbd:first-child{border-start-end-radius:0;border-end-end-radius:0}
.rs-kbd-pair .rs-kbd + .rs-kbd{margin-inline-start:-1px;border-start-start-radius:0;border-end-start-radius:0}

/* ── One-time code: one quiet cell per character ── */
.rs-otp{display:flex;gap:8px}
.rs-otp input{width:40px;height:48px;text-align:center;font-size:18px;font-weight:600;font-variant-numeric:tabular-nums;color:var(--text);background:var(--bg);border:1px solid var(--divider);border-radius:var(--radius-sm);outline:none;font-family:inherit;padding:0}
.rs-otp input:focus{border-color:var(--accent)}

/* ── Menubar: dropdown menus in a hairline strip ── */
.rs-menubar{display:inline-flex;align-items:center;gap:2px;border:1px solid var(--divider);border-radius:var(--radius-sm);padding:2px}
.rs-menubar .rs-select{min-width:0}
.rs-menubar .rs-dropdown{border:none;padding:6px 10px;font-size:13px;gap:6px}
.rs-menubar .rs-menu{min-width:180px;right:auto}

/* ── Navigation menu: quiet links; the current page is ink ── */
.rs-nav{display:flex;align-items:center;gap:22px}
.rs-nav a{font-size:14px;font-weight:500;letter-spacing:-.01em;color:var(--text-secondary);text-decoration:none;transition:color var(--duration-snap) var(--ease)}
.rs-nav a:hover,.rs-nav a[aria-current="page"]{color:var(--text)}

/* ── Sidebar: one 204 module rail, flush items, hairline edge.
   Last item keeps air before the foot rule. ── */
.rs-sidebar{width:204px;min-height:204px;display:flex;flex-direction:column;border:1px solid var(--divider);background:var(--bg);border-radius:0}
.rs-sidebar-head{padding:16px 20px;font-size:13px;font-weight:600;letter-spacing:-.01em;color:var(--text);border-bottom:1px solid var(--divider)}
.rs-sidebar-nav{display:flex;flex-direction:column;padding:8px 0 32px;flex:1}
.rs-sidebar-item,
.rs-sidebar-item:link,
.rs-sidebar-item:visited,
.rs-sidebar-item:any-link{
  display:block;
  padding:8px 20px;
  font-size:13px;
  font-weight:500;
  letter-spacing:-.01em;
  color:var(--text-secondary);
  text-decoration:none;
}
.rs-sidebar-item:last-child{padding-bottom:32px}
.rs-sidebar-item:hover,.rs-sidebar-item[aria-current="page"]{color:var(--text)}
.rs-sidebar-label{padding:16px 20px 4px;font-size:12px;font-weight:600;letter-spacing:-.01em;color:var(--text-secondary)}
.rs-sidebar-foot{padding:12px 20px;border-top:1px solid var(--divider);font-size:12px;font-weight:500;letter-spacing:-.01em;color:var(--text-secondary)}

/* ── Carousel: native scroll snap; edges feather; slides are Raster chrome ── */
.rs-carousel{position:relative;width:100%;max-width:100%}
.rs-carousel-track{display:flex;gap:var(--gutter);overflow-x:auto;scroll-snap-type:x mandatory;scroll-behavior:smooth;scrollbar-width:none;-webkit-mask-image:linear-gradient(to right,transparent 0,#000 28px,#000 calc(100% - 36px),transparent 100%);mask-image:linear-gradient(to right,transparent 0,#000 28px,#000 calc(100% - 36px),transparent 100%);padding:2px 0}
.rs-carousel-track::-webkit-scrollbar{display:none}
.rs-carousel-track>*{scroll-snap-align:start;flex-shrink:0}
.rs-carousel-slide{box-sizing:border-box;width:140px;padding:14px;border:1px solid var(--divider);border-radius:var(--radius-sm);box-shadow:none;background:var(--bg)}
.rs-carousel-nav{display:flex;gap:5px;margin-top:10px}
@media(prefers-reduced-motion:reduce){.rs-carousel-track{scroll-behavior:auto}}

/* ── Resizable: two panes on a draggable hairline ── */
.rs-split{display:flex;width:100%}
.rs-split-pane{min-width:0;overflow:hidden}
.rs-split-handle{flex-shrink:0;width:9px;margin:0 -4px;position:relative;z-index:5;cursor:col-resize;background:none;border:none;padding:0;touch-action:none}
.rs-split-handle::after{content:"";position:absolute;left:4px;top:0;bottom:0;width:1px;background:var(--divider);transition:background-color var(--duration-snap) var(--ease)}
.rs-split-handle:hover::after,.rs-split-handle:focus-visible::after{background:var(--text)}
.rs-split-handle:focus-visible{outline:none}

/* ── Combobox: the quiet field with a filtered overlay ── */
.rs-combobox{position:relative;display:inline-block;min-width:200px}
.rs-combobox .rs-menu{position:absolute;top:100%;left:0;right:0;z-index:50;margin-top:6px;max-height:240px;overflow-y:auto}
.rs-combobox-empty{padding:10px 12px;font-size:13px;letter-spacing:-.01em;color:var(--text-secondary)}

/* ── Command: one input, everything reachable ── */
.rs-command{width:480px;max-width:90vw;padding:0;overflow:hidden}
.rs-command-input{width:100%;border:none;border-bottom:1px solid var(--divider);background:none;font-family:inherit;font-size:14px;letter-spacing:-.01em;color:var(--text);padding:14px 16px;outline:none}
.rs-command-input::placeholder{color:var(--text-secondary)}
.rs-command-list{max-height:320px;overflow-y:auto;padding:6px}
.rs-command-group{font-size:11px;font-weight:600;letter-spacing:-.01em;color:var(--text-secondary);padding:8px 10px 4px}
.rs-command-item{display:flex;align-items:center;justify-content:space-between;gap:12px;width:100%;text-align:left;border:none;background:none;font-family:inherit;font-size:13.5px;letter-spacing:-.01em;color:var(--text);padding:8px 10px;border-radius:var(--radius-sm);cursor:pointer}
.rs-command-item-active{background:var(--divider-subtle)}
.rs-command-hint{font-size:11px;color:var(--text-secondary)}
.rs-command-empty{padding:20px;text-align:center;font-size:13px;color:var(--text-secondary)}

/* ── Calendar: a month of quiet squares; selected is ink.
   Day corners follow inherited --rs-in (Steve’s innerRadius) when nested. ── */
.rs-cal{width:252px}
.rs-cal-head{display:flex;justify-content:space-between;align-items:center;min-height:26px;margin-bottom:8px}
.rs-cal-title{font-size:13px;font-weight:600;letter-spacing:-.01em;line-height:26px;color:var(--text)}
.rs-cal-nav{display:flex;gap:5px}
/* Inter ‹ › sit high in the em; the 26px nav chrome reads ~1px above the title ink. */
.rs-cal-nav .rs-page{transform:translateY(1px)}
.rs-cal-grid{display:grid;grid-template-columns:repeat(7,36px)}
.rs-cal-dow{font-size:11px;font-weight:500;color:var(--text-secondary);text-align:center;padding:4px 0}
.rs-cal-day{width:36px;height:36px;display:flex;align-items:center;justify-content:center;font-size:13px;font-variant-numeric:tabular-nums;color:var(--text);background:none;border:none;border-radius:var(--rs-in, var(--radius-sm));cursor:pointer;font-family:inherit;padding:0}
.rs-cal-day:hover{background:var(--divider-subtle)}
.rs-cal-day-out{color:var(--text-secondary);opacity:.45}
.rs-cal-day-today{box-shadow:inset 0 0 0 1px var(--divider)}
.rs-cal-day-selected,.rs-cal-day-selected:hover{background:var(--text);color:var(--bg);font-weight:600}

/* ── Data table: sortable hairline rows ── */
.rs-datatable-sort{background:none;border:none;padding:0;font:inherit;font-weight:600;letter-spacing:inherit;color:inherit;cursor:pointer;display:inline-flex;align-items:center;gap:5px}
.rs-datatable-sort svg{opacity:.45}
.rs-datatable-sort[data-active="true"] svg{opacity:1}
.rs-datatable-empty{padding:24px 20px;text-align:center;font-size:13px;letter-spacing:-.01em;color:var(--text-secondary)}

/* ── Aspect ratio: a box that keeps its proportions ── */
.rs-ratio{position:relative;width:100%;overflow:hidden;border-radius:var(--radius)}
.rs-ratio>*{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}

/* ── Workflow cards: the dashed editable pipeline ── */
.rs-flow{display:grid;grid-template-columns:1fr;gap:var(--gutter)}
@media(min-width:560px){.rs-flow{grid-template-columns:repeat(2,184px);width:fit-content}}
@media(min-width:940px){.rs-flow{grid-template-columns:repeat(3,184px)}}
@media(min-width:1280px){.rs-flow{grid-template-columns:repeat(4,184px)}}
@media(min-width:1448px){.rs-flow{grid-template-columns:repeat(5,184px)}}
.rs-flow-step{position:relative;border:1px dashed var(--divider);border-radius:var(--radius-sm);padding:14px 34px 16px 14px;background:var(--bg);transition:border-color var(--duration-snap) var(--ease)}
.rs-flow-step:hover{border-color:var(--accent)}
.rs-flow-step::after{content:"";position:absolute;top:15px;right:13px;width:8px;height:14px;background-image:radial-gradient(currentColor 1.1px,transparent 1.3px);background-size:4px 5px;color:var(--text-secondary);opacity:.4}
.rs-flow-num{position:relative;z-index:1;display:flex;align-items:center;justify-content:center;width:30px;height:30px;border-radius:50%;border:1px solid var(--divider);background:var(--bg);font-size:13px;font-weight:600;font-variant-numeric:tabular-nums;color:var(--text);margin-bottom:14px}
.rs-flow-step h4{display:inline-block;font-size:14.5px;font-weight:600;letter-spacing:-.01em;color:var(--text);border-bottom:1px dashed var(--divider);padding-bottom:1px;margin:0 0 8px}
.rs-flow-step p{font-size:12.5px;line-height:1.55;color:var(--text-secondary);letter-spacing:-.005em;margin:0}
.rs-flow-subs{display:flex;flex-wrap:wrap;gap:5px;margin-top:11px}
.rs-flow-subs span{font-size:11px;line-height:1;padding:3px 7px;border:1px dashed var(--divider);border-radius:var(--radius-sm);color:var(--text-secondary);letter-spacing:-.005em}
.rs-flow-subs .rs-flow-sub-add{width:18px;padding:3px 0;text-align:center;opacity:.7}
.rs-flow-add{display:flex;align-items:center;gap:8px;margin-top:14px;border:1px dashed var(--divider);border-radius:var(--radius-sm);padding:12px 14px;font-size:13px;font-weight:600;letter-spacing:-.01em;color:var(--text-secondary);background:none;width:184px;max-width:100%;transition:border-color var(--duration-snap) var(--ease),color var(--duration-snap) var(--ease);font-family:inherit;cursor:pointer}
.rs-flow-add:hover{border-color:var(--accent);color:var(--text)}
.rs-flow-plus{display:inline-flex;align-items:center;justify-content:center;width:18px;height:18px;border:1px solid currentColor;border-radius:50%;font-size:13px;line-height:1}

/* ── Assistant panel: monochrome chat surface ── */
.rs-ai{display:flex;flex-direction:column;gap:16px;max-width:560px;border:1px solid var(--divider);border-radius:var(--radius);padding:20px}
.rs-ai-head{display:flex;justify-content:space-between;align-items:center}
.rs-ai-title{font-size:13px;font-weight:600;letter-spacing:-.01em;color:var(--text)}
.rs-ai-status{display:flex;align-items:center;gap:6px;font-size:12px;font-weight:500;color:var(--text-secondary);letter-spacing:-.01em}
.rs-ai-status i{width:6px;height:6px;border-radius:50%;background:var(--text)}
.rs-ai-msg{display:flex;width:100%}
.rs-ai-user{justify-content:flex-end}
.rs-ai-user-block{background:var(--table-alt);border:1px solid var(--divider);border-radius:var(--radius);padding:10px 14px;font-size:13.5px;color:var(--text);letter-spacing:-.01em;max-width:85%}
.rs-ai-reply{font-size:13.5px;line-height:1.6;color:var(--text);letter-spacing:-.01em;margin:0}
.rs-ai-card{border:1px solid var(--divider);border-radius:var(--radius);padding:14px;display:flex;flex-direction:column;align-items:flex-start}
.rs-ai-tag{font-size:10.5px;font-weight:600;letter-spacing:.02em;color:var(--text);border:1px solid var(--divider);border-radius:var(--radius-sm);padding:2px 8px;margin-bottom:10px}
.rs-ai-text{font-size:13px;color:var(--text);line-height:1.5;margin:0}
.rs-ai-done{display:flex;align-items:baseline;gap:8px;margin-top:12px;font-size:12.5px;line-height:1.45;color:var(--text-secondary)}
.rs-ai-done svg{flex-shrink:0;transform:translateY(1.5px);color:var(--text)}
.rs-ai-input{margin-top:2px;border:1px solid var(--divider);border-radius:var(--radius-sm);background:var(--bg);padding:10px 12px;font-size:12.5px;color:var(--text-secondary);display:flex;justify-content:space-between;align-items:center}
.rs-ai-send{color:var(--text);font-weight:600}

/* ── Theme toggle: one mark. Apps pin it top-right; inline sits in flow. ── */
.rs-theme-toggle{position:fixed;top:24px;right:20px;z-index:200;width:24px;height:24px;padding:4px;display:flex;align-items:center;justify-content:center;overflow:hidden;background:none;border:none;border-radius:0;cursor:pointer;color:var(--text-secondary);outline:none;filter:drop-shadow(0 0 12px var(--bg)) drop-shadow(0 0 20px var(--bg))}
.rs-theme-toggle:hover{color:var(--accent)}
.rs-theme-toggle:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
.rs-theme-sun,.rs-theme-moon{width:16px;height:16px;display:block;flex-shrink:0}
.rs-theme-toggle-inline{position:relative;top:auto;right:auto;z-index:1;filter:none}
@media(max-width:480px){.rs-theme-toggle:not(.rs-theme-toggle-inline){right:25px}}

/* ── Callout: paper field, 1px hairline on all sides. Not rounded. No left bar. ── */
.rs-callout{background:var(--bg);border:1px solid var(--divider);border-radius:0;box-shadow:none;padding:16px 20px}
.rs-callout p{font-size:14px;font-weight:500;color:var(--text-secondary);letter-spacing:-.01em;line-height:1.6;margin:0}
.rs-callout p strong{color:var(--text);font-weight:600}
@media(max-width:640px){.rs-callout{padding:14px 16px}}

/* ── References: inline citations, the numbered list, the cite box ──
   The academic register: quiet superscripts, hairline rows, numerals
   hanging in the gutter. */
.rs-cite{font-size:10.5px;font-weight:600;letter-spacing:0;line-height:0;vertical-align:super;white-space:nowrap}
.rs-cite a{color:var(--text-secondary);text-decoration:none;transition:color var(--duration-snap) var(--ease)}
.rs-cite a:hover{color:var(--accent)}
.rs-refs{list-style:none;counter-reset:ref;margin:4px 0 8px;padding:0}
.rs-refs li{counter-increment:ref;position:relative;padding:10px 0;font-size:13px;font-weight:500;line-height:1.65;color:var(--text-secondary);letter-spacing:-.01em;border-bottom:1px solid var(--divider);scroll-margin-top:88px}
.rs-refs li:last-child{border-bottom:none}
.rs-refs li::before{content:counter(ref);position:absolute;left:-16px;top:11px;width:12px;text-align:right;font-size:11px;font-weight:600;color:var(--accent)}
.rs-refs li:target{background:var(--table-alt)}
.rs-ref-authors{color:var(--text);font-weight:500}
.rs-ref-doi{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:11px;color:var(--text-secondary);text-decoration:none;border-bottom:1px solid var(--divider);transition:color var(--duration-snap) var(--ease),border-color var(--duration-snap) var(--ease);word-break:break-all}
.rs-ref-doi:hover{color:var(--text);border-color:var(--accent)}
.rs-cite-box{border:1px solid var(--divider);border-radius:var(--radius);padding:20px;margin-top:8px}
.rs-cite-box-label{font-size:12px;font-weight:600;color:var(--text-secondary);letter-spacing:-.01em;margin-bottom:8px}
.rs-cite-box-text{font-size:13px;font-weight:500;color:var(--text-secondary);line-height:1.7;user-select:all}
.rs-cite-box-text em{font-style:italic}
@media(max-width:640px){.rs-cite-box{padding:14px 16px}}

/* ── Phone scale (≤640): iOS Human Interface, translated into Raster.
   Desktop rules in components/*.css stay the poster. Do not restyle ≥900. ── */
@media(max-width:640px){
  /* Button: full-width 44pt, 16px, flush. Small variant grows with the scale. */
  .rs-btn-primary,.rs-btn-ghost{
    width:100%;
    height:var(--control-h);
    min-height:var(--hit);
    font-size:var(--control-fs);
    padding:0 20px;
    border-radius:0;
  }
  .rs-btn-sm{height:var(--control-h);min-height:var(--hit);font-size:var(--control-fs);padding:0 16px;min-width:0}
  .rs-btn-group{display:flex;width:100%;height:var(--control-h);border-radius:0}
  .rs-btn-group>.rs-btn-primary,.rs-btn-group>.rs-btn-ghost{flex:1;min-width:0}

  /* Field / input: 16px so iOS does not zoom; 44pt hit; label steps up. */
  .rs-field{gap:8px}
  .rs-field-label,.rs-label{font-size:var(--control-label)}
  .rs-input{
    min-height:var(--hit);
    height:var(--control-h);
    font-size:16px;
    padding:0 14px;
    line-height:calc(var(--control-h) - 2px);
    border-radius:0;
  }
  .rs-feedback,.rs-field-hint,.rs-field-error{font-size:14px;line-height:16px;margin:0}
  .rs-form{max-width:none;width:100%;gap:20px}

  /* Textarea / native select */
  .rs-textarea{font-size:16px;padding:12px 14px;border-radius:0;min-height:132px}
  .rs-native-select{min-height:var(--hit);height:var(--control-h);font-size:16px;padding:0 36px 0 14px;line-height:calc(var(--control-h) - 2px);border-radius:0}

  /* Checkbox / radio: 44pt rows, larger mark, 17px label */
  .rs-choice,.rs-radio{
    min-height:var(--hit);
    font-size:17px;
    gap:12px;
  }
  .rs-check{width:22px;height:22px;border-radius:0}
  .rs-check svg{width:16px;height:16px}
  .rs-radio-dot{width:22px;height:22px}
  .rs-radio-on::after{inset:5px}

  /* Switch: square Raster track, not the desktop pill. 44pt hit. */
  .rs-switch,button.rs-switch{
    width:64px;
    height:var(--hit);
    min-width:64px;
    min-height:var(--hit);
    border-radius:0;
    box-sizing:border-box;
  }
  .rs-switch i{
    top:4px;
    left:4px;
    width:36px;
    height:36px;
    border-radius:0;
  }
  .rs-switch-on i{transform:translateX(20px)}

  /* Tabs: full-width equal columns, 44pt, hairline under the set */
  .rs-tabs{
    display:flex;
    align-items:stretch;
    width:100%;
    max-width:none;
    gap:0;
    border-bottom:1px solid var(--divider);
  }
  .rs-tab,button.rs-tab{
    flex:1;
    display:inline-flex;
    align-items:center;
    justify-content:center;
    min-height:var(--hit);
    padding:0 8px;
    font-size:var(--control-fs);
    text-align:center;
  }

  /* Stepper: 44pt dots stay circles; hairlines still meet the marks. */
  .rs-steps{gap:0}
  .rs-step{min-width:0;gap:6px}
  .rs-step-dot{
    width:var(--hit);
    height:var(--hit);
    border-radius:50%;
    font-size:15px;
    margin-bottom:8px;
  }
  .rs-step-line{top:calc(var(--hit) / 2);left:var(--hit)}
  .rs-step-name{font-size:var(--control-fs)}
  .rs-step-sub{font-size:13px}

  /* Accordion / collapsible: 44pt headers, 17px */
  .rs-acc-item summary{
    min-height:var(--hit);
    padding:14px 0;
    font-size:17px;
  }
  .rs-acc-body{padding:0 0 20px;font-size:16px}
  .rs-disclosure summary{
    min-height:var(--hit);
    font-size:17px;
  }
  .rs-disclosure-body{font-size:16px;padding:12px 0 0}

  /* Menu / select / combobox: 44pt trigger and rows, sheet-like overlay */
  .rs-select,.rs-combobox{width:100%;min-width:0;display:block}
  .rs-dropdown,button.rs-dropdown{
    min-height:var(--hit);
    font-size:var(--control-fs);
    padding:12px 14px;
    border-radius:0;
  }
  .rs-menu{
    border-radius:0;
    box-shadow:none;
    margin-top:0;
  }
  .rs-menu-item,button.rs-menu-item{
    min-height:var(--hit);
    font-size:var(--control-fs);
    padding:12px 14px;
    display:flex;
    align-items:center;
  }
  .rs-combobox-empty{padding:14px;font-size:15px}

  /* Toggle / segmented: full-width 44pt bar, flush */
  .rs-toggle{
    height:var(--hit);
    min-height:var(--hit);
    min-width:var(--hit);
    padding:0 14px;
    font-size:var(--control-fs);
    border-radius:0;
  }
  .rs-toggle-group{display:flex;width:100%;height:var(--hit);border-radius:0}
  .rs-toggle-group .rs-toggle{flex:1;border:0;border-radius:0;margin:0}

  /* Slider: thicker track, larger thumb, ±20px hit */
  .rs-slider{height:4px;margin:20px 0;border-radius:0}
  .rs-slider-fill{border-radius:0}
  .rs-slider-thumb{width:22px;height:22px;border-radius:0}
  .rs-slider input[type=range]{top:-20px;bottom:-20px}

  /* Pagination + carousel / calendar nav (they reuse .rs-page) */
  .rs-pages{gap:8px;flex-wrap:wrap}
  .rs-page,button.rs-page{
    width:var(--hit);
    height:var(--hit);
    min-width:var(--hit);
    min-height:var(--hit);
    font-size:var(--control-fs);
    border-radius:0;
  }
  .rs-carousel-nav{gap:8px;margin-top:14px}

  /* Toast: full-width bottom sheet, no shadow, 0 radius */
  .rs-toasts{
    left:0;
    right:0;
    bottom:0;
    align-items:stretch;
    gap:0;
  }
  .rs-toast{
    max-width:none;
    width:100%;
    border-radius:0;
    box-shadow:none;
    padding:16px 20px;
    padding-bottom:calc(16px + env(safe-area-inset-bottom,0px));
  }
  .rs-toast-title{font-size:16px}
  .rs-toast-body{font-size:15px;margin-top:4px}
  .rs-toast-action,.rs-toast .rs-btn-ghost,.rs-toast .rs-btn-primary{
    min-height:var(--hit);
    font-size:var(--control-fs);
  }

  /* Chip: 44pt identifier, more air */
  .rs-chip{
    display:inline-flex;
    align-items:center;
    min-height:var(--hit);
    padding:12px 14px;
    font-size:13px;
    border-radius:0;
  }

  /* Item: 44pt+ cells, 16px title */
  .rs-item{min-height:var(--hit);padding:14px 0}
  .rs-item-title{font-size:var(--control-fs)}
  .rs-item-desc{font-size:14px}
  .rs-item-meta{font-size:14px}

  /* Command: 44pt input and rows */
  .rs-command{width:100%;max-width:100%}
  .rs-command-input{min-height:var(--hit);font-size:16px;padding:14px 16px}
  .rs-command-item{
    min-height:var(--hit);
    font-size:var(--control-fs);
    padding:12px 14px;
    border-radius:0;
  }
  .rs-command-group{font-size:13px;padding:12px 14px 6px}
  .rs-command-empty{padding:24px;font-size:15px}

  /* Inline form: field + action share a 44pt row */
  .rs-inline-field{min-height:var(--hit);padding:0;border-radius:0;align-items:stretch}
  .rs-inline-input{font-size:16px;padding:0 14px;min-height:var(--hit)}
  .rs-inline-btn{height:var(--hit);min-height:var(--hit);font-size:var(--control-fs);padding:0 16px;border-radius:0}

  /* OTP / input group */
  .rs-otp{width:100%;gap:8px}
  .rs-otp input{flex:1;width:auto;min-width:0;min-height:var(--hit);height:var(--hit);font-size:18px;border-radius:0}
  .rs-input-group{border-radius:0}
  .rs-input-addon{min-height:var(--hit);padding:0 14px;font-size:var(--control-fs)}
  .rs-input-group .rs-input{min-height:var(--hit)}

  /* Nav / menubar / breadcrumbs */
  .rs-nav{flex-wrap:wrap;gap:0}
  .rs-nav a{
    display:inline-flex;
    align-items:center;
    min-height:var(--hit);
    padding:0 12px;
    font-size:var(--control-fs);
  }
  .rs-menubar{width:100%;padding:0;border-radius:0}
  .rs-menubar .rs-dropdown{min-height:var(--hit);padding:12px 14px;font-size:var(--control-fs)}
  .rs-crumbs{font-size:var(--control-fs);flex-wrap:wrap;align-items:center;gap:6px}
  .rs-crumbs a,.rs-crumbs .rs-crumbs-link,.rs-crumbs-here{
    display:inline-flex;
    align-items:center;
    min-height:var(--hit);
  }

  /* Calendar: 36×36 day squares (PR 17). Nav chevrons stay 44pt. */
  .rs-cal{width:252px}
  .rs-cal-head{min-height:var(--hit);align-items:center}
  .rs-cal-title{font-size:var(--control-fs)}
  .rs-cal-nav{gap:8px;flex-shrink:0}
  .rs-cal-grid{grid-template-columns:repeat(7,36px);width:252px}
  .rs-cal-dow{font-size:13px;padding:4px 0}
  .rs-cal-day{
    width:36px;
    height:36px;
    min-width:36px;
    min-height:36px;
    box-sizing:border-box;
  }

  /* Sidebar: 44pt rows, 16px. Desktop padding:8px 0 32px stays in sidebar.css. */
  .rs-sidebar{width:100%}
  .rs-sidebar-head{font-size:var(--control-fs);padding:16px 20px;min-height:var(--hit);display:flex;align-items:center}
  .rs-sidebar-item,.rs-sidebar-item:link,.rs-sidebar-item:visited,.rs-sidebar-item:any-link{
    display:flex;
    align-items:center;
    min-height:var(--hit);
    padding:12px 20px;
    font-size:var(--control-fs);
  }
  .rs-sidebar-item:last-child{padding-bottom:32px}
  .rs-sidebar-label{font-size:var(--control-label);padding:16px 20px 8px}
  .rs-sidebar-foot{font-size:14px;min-height:var(--hit);display:flex;align-items:center}

  /* Dialog / alert-dialog: near-full width, stacked actions, no shadow */
  .rs-dialog{
    max-width:calc(100vw - 32px);
    width:calc(100vw - 32px);
    box-shadow:none;
    padding:24px 20px;
  }
  .rs-dialog-title{font-size:18px;margin-bottom:10px}
  .rs-dialog-body{font-size:16px;margin:0 0 20px}
  .rs-dialog-actions{flex-direction:column;align-items:stretch;gap:10px}

  /* Sheet: full width, no shadow */
  dialog.rs-sheet{
    width:100%;
    max-width:100%;
    box-shadow:none;
    padding:24px 20px;
  }
  .rs-sheet-title{font-size:18px}
  .rs-sheet-body{font-size:16px}

  /* Drawer type */
  .rs-drawer-title{font-size:18px}
  .rs-drawer-body{font-size:16px}

  /* Popover: wider, 16px, flush */
  .rs-popover{width:min(320px,calc(100vw - 32px));font-size:16px;border-radius:0;box-shadow:none;padding:16px}
  .rs-popover-title{font-size:16px}

  /* Table: undo the 12px shrink; 44pt-ish rows */
  .rs-table{font-size:16px}
  .rs-table th{padding:14px 12px;font-size:15px}
  .rs-table td{padding:14px 12px;font-size:16px}

  /* Split: stack panes; 44pt row handle */
  .rs-split{flex-direction:column}
  .rs-split-handle{
    width:auto;
    height:var(--hit);
    margin:-4px 0;
    cursor:row-resize;
  }
  .rs-split-handle::after{left:0;right:0;top:50%;bottom:auto;width:auto;height:1px}

  /* Theme toggle (library): 44pt. Site chrome uses .theme-toggle separately. */
  .rs-theme-toggle{width:var(--hit);height:var(--hit);min-width:var(--hit);min-height:var(--hit);padding:12px}

  /* Empty action stretches with the primary */
  .rs-empty-action{width:100%}

  /* Hover card / tooltip type on phone */
  .rs-hover-card-panel{width:min(280px,calc(100vw - 32px));font-size:15px;border-radius:0;box-shadow:none}
  .rs-tip::after{font-size:13px;padding:8px 12px;border-radius:0}
}

/* Touch: no hover-only reveal. Focus / press shows the overlay. */
@media(hover:none){
  .rs-btn-primary:hover{opacity:1}
  .rs-btn-primary:active{opacity:.85}
  .rs-btn-ghost:hover{background:transparent;border-color:var(--divider)}
  .rs-btn-ghost:active{background:var(--divider);border-color:transparent}
  .rs-cal-day:hover{background:none}
  .rs-cal-day:active{background:var(--divider-subtle)}
  .rs-hover-card:hover .rs-hover-card-panel{opacity:0;visibility:hidden}
  .rs-hover-card:focus-within .rs-hover-card-panel,
  .rs-hover-card:active .rs-hover-card-panel{opacity:1;visibility:visible}
  .rs-tip:hover::after{opacity:0}
  .rs-tip:focus-within::after,
  .rs-tip:active::after{opacity:1}
  .rs-link:hover{border-color:var(--divider)}
  .rs-link:active{border-color:var(--accent)}
  .rs-link-underline:hover{background-image:linear-gradient(var(--divider),var(--divider))}
  .rs-link-underline:active{background-image:linear-gradient(var(--accent),var(--accent))}
}

/* ── Reduced motion: nothing loops, nothing slides, nothing enters ── */
@media(prefers-reduced-motion:reduce){
  .rs-reveal,.rs-crumb-bar .rs-crumbs,.rs-tip::after,.rs-hover-card-panel{transition:none}
  .rs-subscribed,.rs-toast{animation:none}
  .rs-theme-sun,.rs-theme-moon{transition:none}
  .rs-spinner svg{animation:none}
}

css.compat:
/* RASTER COMPAT, GENERATED. Re-emits Raster rules under the 0.1
   class names (bb-*, lib-*, bare table elements) so sites built on
   them keep working. Link this after raster.css; drop it once your
   markup uses the rs- names. */

/* ── Base ──
   Raster owns the page: paper on html, ink on body, and quiet
   gutter verticals on html::before so overflow-x:clip cannot drop
   them. --grid-pos: 20px 0 puts the first tile line on the left
   20px gutter; that utmost left gutter must paint. Do not clip
   it. No 204 horizontals — those cage the type. Homepage and
   About kill this overlay and keep boxed cells only. */
html{scroll-behavior:smooth;font-size:16px;overflow-x:clip;background-color:var(--bg)}
html::before{
  content:"";
  position:fixed;
  inset:0;
  z-index:0;
  pointer-events:none;
  background-image:var(--grid-image);
  background-size:var(--grid-size) 100%;
  background-repeat:repeat-x;
  background-position:var(--grid-pos)
}
body{
  position:relative;
  z-index:1;
  overflow-x:clip;
  background-color:transparent;
  color:var(--text);
  font-family:Inter,-apple-system,BlinkMacSystemFont,'Segoe UI',system-ui,sans-serif;
  font-weight:500;
  line-height:1.6;
  transition:var(--transition);
  -webkit-font-smoothing:antialiased;
}

/* ── Utilities ── */
.rs-sr{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
.rs-sr:focus-visible+.rs-check,.rs-sr:focus-visible+.bb-radio-dot,.rs-sr:focus-visible+.rs-switch{outline:1.5px solid var(--text);outline-offset:2px}

/* ── Type scale ──
   Hierarchy from weight, color, and position; never all caps.
   --text-scale (Appearance → Text size) multiplies reading type only. */
.rs-t-xl{font-size:calc(clamp(34px,5vw,52px) * var(--text-scale, 1));font-weight:600;letter-spacing:-.035em;line-height:1.05;color:var(--text);margin:0;text-wrap:balance}
.rs-t-display{font-size:calc(38px * var(--text-scale, 1));font-weight:600;letter-spacing:-.03em;line-height:1.15;color:var(--text);margin:0;text-wrap:balance}
.rs-t-title{font-size:calc(22px * var(--text-scale, 1));font-weight:600;letter-spacing:-.02em;line-height:1.3;color:var(--text);margin:0;text-wrap:balance}
.rs-t-sub{font-size:calc(17px * var(--text-scale, 1));font-weight:500;letter-spacing:-.01em;line-height:1.5;color:var(--text-secondary);margin:0;text-wrap:pretty}
.rs-t-body{font-size:calc(15px * var(--text-scale, 1));font-weight:500;letter-spacing:-.01em;line-height:1.6;color:var(--text);margin:0;text-wrap:pretty}
.rs-t-label{font-size:calc(13px * var(--text-scale, 1));font-weight:600;letter-spacing:-.01em;line-height:1.3;color:var(--text);margin:0}

/* ── Inline code ── */
.bb-code{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:.88em;color:var(--text);background:var(--table-alt);padding:1px 5px;border-radius:var(--radius-sm);letter-spacing:0}

/* ── Buttons ── */
.bb-btn-primary{font-family:inherit;font-size:14px;font-weight:600;letter-spacing:-.01em;display:inline-flex;align-items:center;justify-content:center;gap:8px;height:40px;padding:0 22px;background:var(--text);color:var(--bg);border:1px solid transparent;border-radius:var(--radius-sm);cursor:pointer;transition:opacity var(--duration-snap) var(--ease)}
.bb-btn-primary:hover{opacity:.85}
.bb-btn-primary:disabled{opacity:.4;cursor:not-allowed}
.bb-btn-ghost{font-family:inherit;font-size:14px;font-weight:500;letter-spacing:-.01em;display:inline-flex;align-items:center;justify-content:center;gap:8px;height:40px;padding:0 22px;background:transparent;color:var(--text);border:1px solid var(--divider);border-radius:var(--radius-sm);cursor:pointer;transition:background-color var(--duration-snap) var(--ease),color var(--duration-snap) var(--ease)}
.bb-btn-ghost:hover{background:var(--divider);border-color:transparent}
.bb-btn-ghost:disabled{opacity:.4;cursor:not-allowed;background:transparent;border-color:var(--divider)}
.bb-btn-primary:focus-visible,.bb-btn-ghost:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
.bb-btn-sm{height:36px;padding:0 14px;font-size:13px;min-width:104px}

/* ── Button group: flush joined actions, one hairline between ──
   The group owns the outer stroke. Join ink is --divider (chrome
   gridline) in both schemes. A 1px gap on a divider field is the
   rule; child border:0 cannot eat it. Ghosts sit on paper. */
.rs-btn-group{
  --rs-out:var(--radius-sm);
  --rs-gap:0px;
  --rs-in:max(0px,calc(var(--rs-out) - var(--rs-gap)));
  display:inline-flex;
  align-items:stretch;
  box-sizing:border-box;
  height:40px;
  border:1px solid var(--divider);
  border-radius:var(--rs-out);
  background:var(--divider);
  gap:1px;
  overflow:hidden
}
.rs-btn-group:has(> .bb-btn-sm){height:36px}
.rs-btn-group > .bb-btn-primary,.rs-btn-group > .bb-btn-ghost{box-sizing:border-box;height:auto;border:0;border-radius:0;margin:0}
.rs-btn-group > .bb-btn-ghost{background:var(--bg)}
.rs-btn-group > .bb-btn-ghost:hover{background:var(--divider)}
.rs-btn-group > .bb-btn-ghost:disabled{background:var(--bg)}
.rs-btn-group > .bb-btn-primary{position:relative;z-index:1}

/* ── Text link: underlined by its hairline, never colored ── */
.bb-link-demo{font-size:14px;color:var(--accent);text-decoration:none;font-weight:500;letter-spacing:-.01em;border-bottom:1px solid var(--divider);transition:border-color var(--duration-snap) var(--ease)}
.bb-link-demo:hover{border-color:var(--accent)}
.bb-link-demo:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
/* Gradient variant: the underline is drawn one pixel inside each end,
   so it never touches a neighbouring glyph. Hover paints it ink. */
.rs-link-underline{color:var(--text);text-decoration:none;border-bottom:none;background-image:linear-gradient(var(--divider),var(--divider));background-size:calc(100% - 1px) 1px;background-position:1px 100%;background-repeat:no-repeat;transition:background-image var(--duration-snap) var(--ease)}
.rs-link-underline:hover{background-image:linear-gradient(var(--accent),var(--accent))}

/* ── Field: quiet input: hairline border, ink focus, label above ──
   Control height matches Button (40 / --control-h). Label and hint
   sit on a 16px line-box so the 1px hairline lands on integer y.
   Gaps are 8px (4/8). */
.rs-field{width:100%;display:flex;flex-direction:column;gap:8px}
.rs-field-label{font-size:12px;font-weight:600;color:var(--text-secondary);letter-spacing:-.01em;line-height:16px}
.bb-sig-input{
  --rs-out:var(--radius-sm);
  --rs-gap:0px;
  --rs-in:max(0px,calc(var(--rs-out) - var(--rs-gap)));
  box-sizing:border-box;
  height:var(--control-h);
  border:1px solid var(--divider);
  border-radius:var(--rs-out);
  background:var(--bg);
  color:var(--text);
  font-size:14px;
  line-height:calc(var(--control-h) - 2px);
  padding:0 10px;
  outline:none;
  font-family:inherit
}
.bb-sig-input:focus{border-color:var(--accent)}
.rs-input{width:100%}
.rs-input-ok{border-color:var(--text) !important}
.rs-feedback{display:flex;align-items:center;gap:8px;font-size:12px;font-weight:500;color:var(--text-secondary);letter-spacing:-.01em;line-height:16px;margin:0;min-height:16px}
.rs-feedback-ok{color:var(--text)}
.rs-feedback svg{flex-shrink:0}
.rs-field-hint{margin:0;font-size:12px;font-weight:500;color:var(--text-secondary);letter-spacing:-.01em;line-height:16px}
.rs-field-error{margin:0;font-size:12px;font-weight:500;color:var(--text);letter-spacing:-.01em;line-height:16px}
.rs-form{display:flex;flex-direction:column;gap:16px;max-width:388px;margin:0}
.rs-label{font-size:12px;font-weight:600;color:var(--text-secondary);letter-spacing:-.01em;line-height:16px}

/* ── Input group: addon and field share one hairline.
   Outer radius is the standalone input; innerRadius with no pad. ── */
.rs-input-group{
  --rs-out:var(--radius-sm);
  --rs-gap:0px;
  --rs-in:max(0px,calc(var(--rs-out) - var(--rs-gap)));
  display:flex;
  align-items:stretch;
  box-sizing:border-box;
  width:100%;
  height:var(--control-h);
  border:1px solid var(--divider);
  border-radius:var(--rs-out);
  background:var(--bg);
  overflow:hidden
}
.rs-input-group:focus-within{border-color:var(--accent)}
.rs-input-addon{display:flex;align-items:center;padding:0 10px;font-size:13px;font-weight:500;letter-spacing:-.01em;color:var(--text-secondary);background:var(--table-alt);white-space:nowrap}
.rs-input-group > * + *{border-inline-start:1px solid var(--divider)}
.rs-input-group .bb-sig-input{border:none;border-radius:var(--rs-in);flex:1;min-width:0;height:auto;line-height:calc(var(--control-h) - 2px)}
.rs-input-group .bb-sig-input:focus{outline:none}
.rs-input-group-end .rs-input-addon{border-inline-start:1px solid var(--divider)}

/* ── Radio: the dot is ink, never a hue ── */
.bb-radio{display:flex;align-items:center;gap:9px;font-size:14px;color:var(--text);letter-spacing:-.01em}
.bb-radio-dot{width:16px;height:16px;border-radius:50%;border:1.5px solid var(--divider);position:relative;flex-shrink:0}
.bb-radio-on{border-color:var(--text)}
.bb-radio-on::after{content:'';position:absolute;inset:3px;border-radius:50%;background:var(--text)}

/* ── Slider: thin track with ink fill and 14px thumb ── */
.bb-slider{position:relative;height:2px;background:var(--divider);border-radius:1px;margin:10px 0}
.bb-slider-fill{position:absolute;left:0;top:0;bottom:0;background:var(--text);border-radius:1px}
.bb-slider-thumb{position:absolute;top:50%;transform:translate(-50%,-50%);width:14px;height:14px;border-radius:50%;background:var(--bg);border:1.5px solid var(--text)}
.bb-slider input[type=range]{position:absolute;left:0;right:0;top:-8px;bottom:-8px;width:100%;height:auto;opacity:0;cursor:pointer;margin:0}
.bb-slider:has(input[type=range]:focus-visible) .bb-slider-thumb{outline:1.5px solid var(--text);outline-offset:2px}

/* ── Progress: the percentage lives in the label, never in the bar ── */
.rs-progress-head{display:flex;justify-content:space-between;font-size:12px;font-weight:500;color:var(--text-secondary);letter-spacing:-.01em;margin-bottom:7px}
.bb-progress{height:4px;background:var(--divider-subtle);border-radius:2px;overflow:hidden}
.bb-progress span{display:block;height:100%;background:var(--text);border-radius:2px}

/* ── Tabs: one line of type. Hairline on the active tab only. ── */
.bb-tabs{display:flex;align-items:baseline;gap:22px;max-width:360px;border:none;box-shadow:none;background:none}
.bb-tab,
button.bb-tab{
  -webkit-appearance:none;
  appearance:none;
  padding:8px 0;
  font-size:14px;
  font-family:inherit;
  color:var(--text-secondary);
  letter-spacing:-.01em;
  text-decoration:none;
  background:none;
  background-image:none;
  box-shadow:none;
  border:none;
  border-radius:0;
  cursor:pointer;
  text-align:left;
}
.bb-tab-active,
button.bb-tab.bb-tab-active{
  color:var(--text);
  font-weight:600;
  border:none;
  box-shadow:inset 0 -1px 0 var(--text);
}

/* ── Breadcrumbs: one ink trail. Slashes at 40%. Current page is full ink.
   Ancestors stay Inter/ink — never a UA :link or :visited color, never an accent. ── */
.bb-crumbs-demo{font-size:13px;color:var(--text);letter-spacing:-.01em;display:flex;align-items:baseline;gap:8px}
.bb-crumbs-demo a,
.bb-crumbs-demo a:link,
.bb-crumbs-demo a:visited,
.bb-crumbs-demo a:hover,
.bb-crumbs-demo a:active,
.bb-crumbs-demo a:focus,
.bb-crumbs-demo a:focus-visible,
.bb-crumbs-demo a:any-link,
.bb-crumbs-demo a:-webkit-any-link,
.bb-crumbs-demo .rs-crumbs-link{
  color:var(--text);
  text-decoration:none;
  background:none;
}
.bb-crumbs-demo a,
.bb-crumbs-demo a:link,
.bb-crumbs-demo a:visited,
.bb-crumbs-demo a:any-link,
.bb-crumbs-demo a:-webkit-any-link,
.bb-crumbs-demo .rs-crumbs-link{opacity:.55}
.bb-crumbs-demo a:hover,.bb-crumbs-demo a:focus-visible{opacity:1}
.bb-crumbs-demo-sep{color:var(--text);opacity:.4}
.bb-crumbs-demo-here{color:var(--text);opacity:1}

/* ── Crumb bar: fixed top bar in the house chrome ──
   Transparent at rest; once the page cover scrolls away it gains the
   paper background and its bottom hairline, and the breadcrumbs
   appear. From 900px the root crumb holds the TOC column; the inner row
   starts one module in at the 1024px rail. */
.rs-crumb-bar{position:fixed;top:0;left:0;right:0;z-index:160;display:flex;align-items:center;height:72px;font-size:13px;font-weight:500;letter-spacing:-.01em;line-height:1.3;background:none;border-bottom:1px solid transparent;transition:var(--transition)}
.rs-crumb-bar-scrolled{background:var(--bg);border-bottom-color:var(--divider)}
.rs-crumb-bar-inner{display:flex;align-items:center;gap:20px;width:100%;min-width:0;padding:0 56px 0 76px}
.rs-crumb-bar .bb-crumbs-demo{margin:0;min-width:0;overflow:hidden;white-space:nowrap;opacity:0;pointer-events:none;transition:opacity var(--duration) var(--ease)}
.rs-crumb-bar-scrolled .bb-crumbs-demo{opacity:1;pointer-events:auto}
.rs-crumb-bar a{color:inherit;text-decoration:none}
.rs-crumb-root{flex-shrink:0;color:var(--text);text-decoration:none;transition:color var(--duration-snap) var(--ease)}
.rs-crumb-bar .bb-crumbs-demo-here{overflow:hidden;text-overflow:ellipsis}
/* Root abbreviation: the short name shows only on phones, leaving the
   path room to dock and ellipsize. */
.rs-crumb-root-short{display:none}
@media(min-width:900px){.rs-crumb-root{width:184px}}
@media(min-width:1024px){.rs-crumb-bar-inner{margin-left:204px;padding-left:var(--pad)}}
@media(max-width:899px){.rs-crumb-bar-inner{gap:6px}.rs-crumb-root{font-weight:600}}
@media(max-width:640px){
  .rs-crumb-bar{height:64px;font-size:12px}
  .rs-crumb-bar-inner{padding:0 50px 0 62px}
  .rs-crumb-root-full{display:none}
  .rs-crumb-root-short{display:inline}
}
@media(max-width:480px){.rs-crumb-bar-inner{padding:0 56px 0 74px}}

/* ── Dropdown + menu: the menu overlays, it never pushes layout ── */
.rs-select{position:relative;display:inline-block;min-width:180px}
.rs-select .bb-menu{position:absolute;top:100%;left:0;right:0;z-index:50;margin-top:6px}
.bb-dropdown{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:9px 12px;border:1px solid var(--divider);border-radius:var(--radius-sm);font-size:14px;color:var(--text);letter-spacing:-.01em}
button.bb-dropdown{cursor:pointer;font-family:inherit;background:none;width:100%}
.bb-menu{
  --rs-out:var(--radius-sm);
  --rs-gap:0px;
  --rs-in:max(0px,calc(var(--rs-out) - var(--rs-gap)));
  border:1px solid var(--divider);
  border-radius:var(--rs-out);
  margin-top:6px;
  overflow:hidden;
  background:var(--bg);
  box-shadow:0 8px 24px rgba(0,0,0,0.06)
}
.bb-menu:has(.rs-cal){
  --rs-gap:12px;
  padding:var(--rs-gap)
}
.bb-menu-item{display:block;padding:9px 12px;font-size:14px;color:var(--text);letter-spacing:-.01em;border-bottom:1px solid var(--divider)}
.bb-menu-item:last-child{border-bottom:none}
.bb-menu-item.bb-menu-item-active,button.bb-menu-item-active{background:var(--divider-subtle)}
button.bb-menu-item{width:100%;text-align:left;cursor:pointer;background:none;border-left:none;border-right:none;border-top:none;font-family:inherit}

/* ── Dialog: one question, two equal actions, no third option.
   Nested actions use Steve’s innerRadius of the frame. ── */
.bb-dialog{
  --rs-out:var(--radius-sm);
  --rs-gap:20px;
  --rs-in:max(0px,calc(var(--rs-out) - var(--rs-gap)));
  max-width:320px;
  border:1px solid var(--divider);
  border-radius:var(--rs-out);
  padding:var(--rs-gap);
  background:var(--bg);
  box-shadow:none
}
dialog.bb-dialog{color:var(--text)}
dialog.bb-dialog::backdrop{background:rgba(0,0,0,0.25)}
.bb-dialog-title{display:block;font-size:15px;font-weight:600;letter-spacing:-.01em;color:var(--text);margin-bottom:6px}
.bb-dialog-body{font-size:13.5px;color:var(--text-secondary);letter-spacing:-.01em;line-height:1.55;margin:0 0 16px}
.bb-dialog-actions{display:flex;justify-content:flex-end;gap:8px}
.bb-dialog .bb-btn-primary,.bb-dialog .bb-btn-ghost{border-radius:var(--rs-in)}

/* ── Badges: outline for recommendations, solid for done, muted for pending ── */
.bb-badge{font-size:11px;font-weight:600;letter-spacing:.02em;color:var(--accent);border:1px solid var(--accent);padding:3px 10px;line-height:1.4;border-radius:var(--radius-sm)}
.bb-badge-solid{font-size:11px;font-weight:600;letter-spacing:.02em;color:var(--bg);background:var(--text);padding:4px 11px;line-height:1.4;border-radius:var(--radius-sm)}
.bb-badge-muted{font-size:11px;font-weight:600;letter-spacing:.02em;color:var(--text-secondary);background:var(--divider-subtle);padding:4px 11px;line-height:1.4;border-radius:var(--radius-sm)}

/* ── Mono chip: technical identifiers ── */
.lib-chip{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:11px;font-weight:500;color:var(--text-secondary);border:1px solid color-mix(in srgb,currentColor 35%,transparent);padding:3px 7px;line-height:1;border-radius:var(--radius-sm)}

/* ── Card: typography stack. No outline. Chrome-square. ── */
.bb-card-demo{
  --rs-out:0;
  --rs-gap:20px;
  --rs-in:max(0px,calc(var(--rs-out) - var(--rs-gap)));
  border:0;
  border-radius:var(--rs-out);
  padding:0;
  max-width:360px;
  background:none;
  box-shadow:none
}
.bb-card-label{font-size:12px;font-weight:600;color:var(--accent);letter-spacing:-.01em;display:block;margin-bottom:6px}
.bb-card-title{font-size:17px;font-weight:600;color:var(--text);letter-spacing:-.02em;margin:0 0 8px}
.bb-card-body{font-size:14px;color:var(--text-secondary);font-weight:500;letter-spacing:-.01em;line-height:1.6;margin:0}
.rs-card-in{
  box-sizing:border-box;
  border:0;
  border-radius:var(--rs-in);
  min-height:0;
  padding:0;
  background:none
}
.bb-card-demo .bb-btn-primary,.bb-card-demo .bb-btn-ghost,.bb-card-demo .bb-sig-input,.bb-card-demo .rs-textarea{border-radius:var(--rs-in)}
.bb-card-demo .rs-btn-group{--rs-out:var(--rs-in);border-radius:var(--rs-out)}

/* ── Concentric radius: Steve Ruiz innerRadius, clamped at 0.
   --rs-in is the closed form of the circular-corner fit.
   Do not reassign --rs-out on the inner frame: that cycles the custom
   property and the used radius becomes 0. ── */
.rs-nest{
  --rs-out:var(--radius-sm);
  --rs-gap:var(--pad);
  --rs-in:max(0px,calc(var(--rs-out) - var(--rs-gap)));
  box-sizing:border-box;
  border:1px solid var(--divider);
  border-radius:var(--rs-out);
  padding:var(--rs-gap);
  background:var(--bg);
}
.rs-nest-in{
  box-sizing:border-box;
  border:1px solid var(--divider);
  border-radius:var(--rs-in);
  min-height:72px;
  background:var(--bg);
  display:flex;
  align-items:flex-end
}
.rs-nest .bb-btn-primary,.rs-nest .bb-btn-ghost{border-radius:var(--rs-in)}

/* ── Table: hairline rows on the open grid; no cell borders ──
   Scoped to table so linking raster.css never restyles a table
   it doesn't own. The compat layer re-emits these on bare elements. */
table{width:calc(100% + 40px);border-collapse:collapse;margin:16px 0 24px -20px;font-size:14px}
table th{text-align:left;font-weight:600;color:var(--text);letter-spacing:-.01em;padding:10px 16px 10px 12px;border-bottom:2px solid var(--divider);font-size:13px}
table th:first-child{padding-left:20px}
table th:last-child{padding-right:20px}
table td{padding:10px 16px 10px 12px;color:var(--text-secondary);font-weight:500;letter-spacing:-.01em;border-bottom:1px solid var(--divider);vertical-align:top}
table td:first-child{padding-left:20px}
table td:last-child{padding-right:20px}
table tr:nth-child(even) td{background:var(--table-alt)}
table td:last-child,table th:last-child{text-align:right}
table tr.rs-total-row td{font-weight:500;color:var(--text);border-top:2px solid var(--divider);border-bottom:2px solid var(--divider)}
@media(max-width:640px){
  table{font-size:12px;width:calc(100% + 2*var(--pad));margin-left:calc(-1*var(--pad));margin-right:calc(-1*var(--pad))}
  table th{padding:8px 10px;font-size:12px}
  table td{padding:8px 10px}
  table th:first-child,table td:first-child{padding-left:var(--pad)}
  table th:last-child,table td:last-child{padding-right:var(--pad)}
}

/* ── Icons: 16 viewBox, 1px currentColor hairline. Size from the svg width. ── */
.bb-icons{display:flex;gap:18px;align-items:center;color:var(--text)}
.rs-icon{display:block;flex-shrink:0;overflow:visible;color:inherit}
.bb-btn-primary .rs-icon,.bb-btn-ghost .rs-icon,.rs-toggle .rs-icon{display:block;flex-shrink:0}
.bb-icons svg{flex-shrink:0}
.bb-icons svg:not([width]){width:16px;height:16px}
.rs-icon-catalog{width:100%;display:flex;flex-direction:column;gap:28px;text-align:left;align-self:stretch}
.rs-icon-group{display:flex;flex-direction:column;gap:12px}
.rs-icon-group-title{margin:0;font-size:12px;font-weight:600;letter-spacing:0;color:var(--text-secondary);text-transform:none}
.rs-icon-grid{display:grid;grid-template-columns:repeat(auto-fill,184px);column-gap:var(--gutter);row-gap:20px;justify-content:start;width:100%}
.rs-icon-cell{display:flex;flex-direction:column;align-items:flex-start;gap:8px;width:184px}
.rs-icon-pair{display:flex;align-items:center;gap:16px;min-height:24px}
.rs-icon-kin{display:flex;align-items:center;gap:8px;min-height:24px}
.rs-icon-label{font-size:11px;line-height:1.3;color:var(--text-secondary);text-transform:none}
@media(max-width:480px){
  .rs-icon-grid{grid-template-columns:minmax(0,1fr)}
  .rs-icon-cell{width:100%}
}

/* ── Menubar: dropdown menus in a hairline strip ── */
.rs-menubar{display:inline-flex;align-items:center;gap:2px;border:1px solid var(--divider);border-radius:var(--radius-sm);padding:2px}
.rs-menubar .rs-select{min-width:0}
.rs-menubar .bb-dropdown{border:none;padding:6px 10px;font-size:13px;gap:6px}
.rs-menubar .bb-menu{min-width:180px;right:auto}

/* ── Combobox: the quiet field with a filtered overlay ── */
.rs-combobox{position:relative;display:inline-block;min-width:200px}
.rs-combobox .bb-menu{position:absolute;top:100%;left:0;right:0;z-index:50;margin-top:6px;max-height:240px;overflow-y:auto}
.rs-combobox-empty{padding:10px 12px;font-size:13px;letter-spacing:-.01em;color:var(--text-secondary)}

/* ── Phone scale (≤640): iOS Human Interface, translated into Raster.
   Desktop rules in components/*.css stay the poster. Do not restyle ≥900. ── */
@media(max-width:640px){
  /* Button: full-width 44pt, 16px, flush. Small variant grows with the scale. */
  .bb-btn-primary,.bb-btn-ghost{
    width:100%;
    height:var(--control-h);
    min-height:var(--hit);
    font-size:var(--control-fs);
    padding:0 20px;
    border-radius:0;
  }
  .bb-btn-sm{height:var(--control-h);min-height:var(--hit);font-size:var(--control-fs);padding:0 16px;min-width:0}
  .rs-btn-group{display:flex;width:100%;height:var(--control-h);border-radius:0}
  .rs-btn-group>.bb-btn-primary,.rs-btn-group>.bb-btn-ghost{flex:1;min-width:0}

  /* Field / input: 16px so iOS does not zoom; 44pt hit; label steps up. */
  .rs-field{gap:8px}
  .rs-field-label,.rs-label{font-size:var(--control-label)}
  .bb-sig-input{
    min-height:var(--hit);
    height:var(--control-h);
    font-size:16px;
    padding:0 14px;
    line-height:calc(var(--control-h) - 2px);
    border-radius:0;
  }
  .rs-feedback,.rs-field-hint,.rs-field-error{font-size:14px;line-height:16px;margin:0}
  .rs-form{max-width:none;width:100%;gap:20px}

  /* Textarea / native select */
  .rs-textarea{font-size:16px;padding:12px 14px;border-radius:0;min-height:132px}
  .rs-native-select{min-height:var(--hit);height:var(--control-h);font-size:16px;padding:0 36px 0 14px;line-height:calc(var(--control-h) - 2px);border-radius:0}

  /* Checkbox / radio: 44pt rows, larger mark, 17px label */
  .rs-choice,.bb-radio{
    min-height:var(--hit);
    font-size:17px;
    gap:12px;
  }
  .rs-check{width:22px;height:22px;border-radius:0}
  .rs-check svg{width:16px;height:16px}
  .bb-radio-dot{width:22px;height:22px}
  .bb-radio-on::after{inset:5px}

  /* Switch: square Raster track, not the desktop pill. 44pt hit. */
  .rs-switch,button.rs-switch{
    width:64px;
    height:var(--hit);
    min-width:64px;
    min-height:var(--hit);
    border-radius:0;
    box-sizing:border-box;
  }
  .rs-switch i{
    top:4px;
    left:4px;
    width:36px;
    height:36px;
    border-radius:0;
  }
  .rs-switch-on i{transform:translateX(20px)}

  /* Tabs: full-width equal columns, 44pt, hairline under the set */
  .bb-tabs{
    display:flex;
    align-items:stretch;
    width:100%;
    max-width:none;
    gap:0;
    border-bottom:1px solid var(--divider);
  }
  .bb-tab,button.bb-tab{
    flex:1;
    display:inline-flex;
    align-items:center;
    justify-content:center;
    min-height:var(--hit);
    padding:0 8px;
    font-size:var(--control-fs);
    text-align:center;
  }

  /* Stepper: 44pt dots stay circles; hairlines still meet the marks. */
  .rs-steps{gap:0}
  .rs-step{min-width:0;gap:6px}
  .rs-step-dot{
    width:var(--hit);
    height:var(--hit);
    border-radius:50%;
    font-size:15px;
    margin-bottom:8px;
  }
  .rs-step-line{top:calc(var(--hit) / 2);left:var(--hit)}
  .rs-step-name{font-size:var(--control-fs)}
  .rs-step-sub{font-size:13px}

  /* Accordion / collapsible: 44pt headers, 17px */
  .rs-acc-item summary{
    min-height:var(--hit);
    padding:14px 0;
    font-size:17px;
  }
  .rs-acc-body{padding:0 0 20px;font-size:16px}
  .rs-disclosure summary{
    min-height:var(--hit);
    font-size:17px;
  }
  .rs-disclosure-body{font-size:16px;padding:12px 0 0}

  /* Menu / select / combobox: 44pt trigger and rows, sheet-like overlay */
  .rs-select,.rs-combobox{width:100%;min-width:0;display:block}
  .bb-dropdown,button.bb-dropdown{
    min-height:var(--hit);
    font-size:var(--control-fs);
    padding:12px 14px;
    border-radius:0;
  }
  .bb-menu{
    border-radius:0;
    box-shadow:none;
    margin-top:0;
  }
  .bb-menu-item,button.bb-menu-item{
    min-height:var(--hit);
    font-size:var(--control-fs);
    padding:12px 14px;
    display:flex;
    align-items:center;
  }
  .rs-combobox-empty{padding:14px;font-size:15px}

  /* Toggle / segmented: full-width 44pt bar, flush */
  .rs-toggle{
    height:var(--hit);
    min-height:var(--hit);
    min-width:var(--hit);
    padding:0 14px;
    font-size:var(--control-fs);
    border-radius:0;
  }
  .rs-toggle-group{display:flex;width:100%;height:var(--hit);border-radius:0}
  .rs-toggle-group .rs-toggle{flex:1;border:0;border-radius:0;margin:0}

  /* Slider: thicker track, larger thumb, ±20px hit */
  .bb-slider{height:4px;margin:20px 0;border-radius:0}
  .bb-slider-fill{border-radius:0}
  .bb-slider-thumb{width:22px;height:22px;border-radius:0}
  .bb-slider input[type=range]{top:-20px;bottom:-20px}

  /* Pagination + carousel / calendar nav (they reuse .rs-page) */
  .rs-pages{gap:8px;flex-wrap:wrap}
  .rs-page,button.rs-page{
    width:var(--hit);
    height:var(--hit);
    min-width:var(--hit);
    min-height:var(--hit);
    font-size:var(--control-fs);
    border-radius:0;
  }
  .rs-carousel-nav{gap:8px;margin-top:14px}

  /* Toast: full-width bottom sheet, no shadow, 0 radius */
  .rs-toasts{
    left:0;
    right:0;
    bottom:0;
    align-items:stretch;
    gap:0;
  }
  .rs-toast{
    max-width:none;
    width:100%;
    border-radius:0;
    box-shadow:none;
    padding:16px 20px;
    padding-bottom:calc(16px + env(safe-area-inset-bottom,0px));
  }
  .rs-toast-title{font-size:16px}
  .rs-toast-body{font-size:15px;margin-top:4px}
  .rs-toast-action,.rs-toast .bb-btn-ghost,.rs-toast .bb-btn-primary{
    min-height:var(--hit);
    font-size:var(--control-fs);
  }

  /* Chip: 44pt identifier, more air */
  .lib-chip{
    display:inline-flex;
    align-items:center;
    min-height:var(--hit);
    padding:12px 14px;
    font-size:13px;
    border-radius:0;
  }

  /* Item: 44pt+ cells, 16px title */
  .rs-item{min-height:var(--hit);padding:14px 0}
  .rs-item-title{font-size:var(--control-fs)}
  .rs-item-desc{font-size:14px}
  .rs-item-meta{font-size:14px}

  /* Command: 44pt input and rows */
  .rs-command{width:100%;max-width:100%}
  .rs-command-input{min-height:var(--hit);font-size:16px;padding:14px 16px}
  .rs-command-item{
    min-height:var(--hit);
    font-size:var(--control-fs);
    padding:12px 14px;
    border-radius:0;
  }
  .rs-command-group{font-size:13px;padding:12px 14px 6px}
  .rs-command-empty{padding:24px;font-size:15px}

  /* Inline form: field + action share a 44pt row */
  .rs-inline-field{min-height:var(--hit);padding:0;border-radius:0;align-items:stretch}
  .rs-inline-input{font-size:16px;padding:0 14px;min-height:var(--hit)}
  .rs-inline-btn{height:var(--hit);min-height:var(--hit);font-size:var(--control-fs);padding:0 16px;border-radius:0}

  /* OTP / input group */
  .rs-otp{width:100%;gap:8px}
  .rs-otp input{flex:1;width:auto;min-width:0;min-height:var(--hit);height:var(--hit);font-size:18px;border-radius:0}
  .rs-input-group{border-radius:0}
  .rs-input-addon{min-height:var(--hit);padding:0 14px;font-size:var(--control-fs)}
  .rs-input-group .bb-sig-input{min-height:var(--hit)}

  /* Nav / menubar / breadcrumbs */
  .rs-nav{flex-wrap:wrap;gap:0}
  .rs-nav a{
    display:inline-flex;
    align-items:center;
    min-height:var(--hit);
    padding:0 12px;
    font-size:var(--control-fs);
  }
  .rs-menubar{width:100%;padding:0;border-radius:0}
  .rs-menubar .bb-dropdown{min-height:var(--hit);padding:12px 14px;font-size:var(--control-fs)}
  .bb-crumbs-demo{font-size:var(--control-fs);flex-wrap:wrap;align-items:center;gap:6px}
  .bb-crumbs-demo a,.bb-crumbs-demo .rs-crumbs-link,.bb-crumbs-demo-here{
    display:inline-flex;
    align-items:center;
    min-height:var(--hit);
  }

  /* Calendar: 36×36 day squares (PR 17). Nav chevrons stay 44pt. */
  .rs-cal{width:252px}
  .rs-cal-head{min-height:var(--hit);align-items:center}
  .rs-cal-title{font-size:var(--control-fs)}
  .rs-cal-nav{gap:8px;flex-shrink:0}
  .rs-cal-grid{grid-template-columns:repeat(7,36px);width:252px}
  .rs-cal-dow{font-size:13px;padding:4px 0}
  .rs-cal-day{
    width:36px;
    height:36px;
    min-width:36px;
    min-height:36px;
    box-sizing:border-box;
  }

  /* Sidebar: 44pt rows, 16px. Desktop padding:8px 0 32px stays in sidebar.css. */
  .rs-sidebar{width:100%}
  .rs-sidebar-head{font-size:var(--control-fs);padding:16px 20px;min-height:var(--hit);display:flex;align-items:center}
  .rs-sidebar-item,.rs-sidebar-item:link,.rs-sidebar-item:visited,.rs-sidebar-item:any-link{
    display:flex;
    align-items:center;
    min-height:var(--hit);
    padding:12px 20px;
    font-size:var(--control-fs);
  }
  .rs-sidebar-item:last-child{padding-bottom:32px}
  .rs-sidebar-label{font-size:var(--control-label);padding:16px 20px 8px}
  .rs-sidebar-foot{font-size:14px;min-height:var(--hit);display:flex;align-items:center}

  /* Dialog / alert-dialog: near-full width, stacked actions, no shadow */
  .bb-dialog{
    max-width:calc(100vw - 32px);
    width:calc(100vw - 32px);
    box-shadow:none;
    padding:24px 20px;
  }
  .bb-dialog-title{font-size:18px;margin-bottom:10px}
  .bb-dialog-body{font-size:16px;margin:0 0 20px}
  .bb-dialog-actions{flex-direction:column;align-items:stretch;gap:10px}

  /* Sheet: full width, no shadow */
  dialog.rs-sheet{
    width:100%;
    max-width:100%;
    box-shadow:none;
    padding:24px 20px;
  }
  .rs-sheet-title{font-size:18px}
  .rs-sheet-body{font-size:16px}

  /* Drawer type */
  .rs-drawer-title{font-size:18px}
  .rs-drawer-body{font-size:16px}

  /* Popover: wider, 16px, flush */
  .rs-popover{width:min(320px,calc(100vw - 32px));font-size:16px;border-radius:0;box-shadow:none;padding:16px}
  .rs-popover-title{font-size:16px}

  /* Table: undo the 12px shrink; 44pt-ish rows */
  table{font-size:16px}
  table th{padding:14px 12px;font-size:15px}
  table td{padding:14px 12px;font-size:16px}

  /* Split: stack panes; 44pt row handle */
  .rs-split{flex-direction:column}
  .rs-split-handle{
    width:auto;
    height:var(--hit);
    margin:-4px 0;
    cursor:row-resize;
  }
  .rs-split-handle::after{left:0;right:0;top:50%;bottom:auto;width:auto;height:1px}

  /* Theme toggle (library): 44pt. Site chrome uses .theme-toggle separately. */
  .rs-theme-toggle{width:var(--hit);height:var(--hit);min-width:var(--hit);min-height:var(--hit);padding:12px}

  /* Empty action stretches with the primary */
  .rs-empty-action{width:100%}

  /* Hover card / tooltip type on phone */
  .rs-hover-card-panel{width:min(280px,calc(100vw - 32px));font-size:15px;border-radius:0;box-shadow:none}
  .rs-tip::after{font-size:13px;padding:8px 12px;border-radius:0}
}

/* Touch: no hover-only reveal. Focus / press shows the overlay. */
@media(hover:none){
  .bb-btn-primary:hover{opacity:1}
  .bb-btn-primary:active{opacity:.85}
  .bb-btn-ghost:hover{background:transparent;border-color:var(--divider)}
  .bb-btn-ghost:active{background:var(--divider);border-color:transparent}
  .rs-cal-day:hover{background:none}
  .rs-cal-day:active{background:var(--divider-subtle)}
  .rs-hover-card:hover .rs-hover-card-panel{opacity:0;visibility:hidden}
  .rs-hover-card:focus-within .rs-hover-card-panel,
  .rs-hover-card:active .rs-hover-card-panel{opacity:1;visibility:visible}
  .rs-tip:hover::after{opacity:0}
  .rs-tip:focus-within::after,
  .rs-tip:active::after{opacity:1}
  .bb-link-demo:hover{border-color:var(--divider)}
  .bb-link-demo:active{border-color:var(--accent)}
  .rs-link-underline:hover{background-image:linear-gradient(var(--divider),var(--divider))}
  .rs-link-underline:active{background-image:linear-gradient(var(--accent),var(--accent))}
}

/* ── Reduced motion: nothing loops, nothing slides, nothing enters ── */
@media(prefers-reduced-motion:reduce){
  .rs-reveal,.rs-crumb-bar .bb-crumbs-demo,.rs-tip::after,.rs-hover-card-panel{transition:none}
  .rs-subscribed,.rs-toast{animation:none}
  .rs-theme-sun,.rs-theme-moon{transition:none}
  .rs-spinner svg{animation:none}
}

