.rs-chart-donut-value{fill:none;stroke:var(--rs-chart-spot);stroke-width:1;stroke-linecap:butt}
.rs-chart-donut-label{fill:var(--text);font-size:12px;font-weight:500;letter-spacing:-.03em;font-variant-numeric:tabular-nums}
