const defaultDateFormat = (d: Date) =>
  d.toLocaleDateString("en", { day: "numeric", month: "long", year: "numeric" });

/** Hairline trigger with a calendar overlay. */
export function DatePicker({
  value,
  onChange,
  placeholder = "Pick a date",
  format = defaultDateFormat,
  className,
  ...props
}: DatePickerProps) {
  const rootRef = React.useRef<HTMLDivElement>(null);
  const [open, setOpen] = React.useState(false);

  React.useEffect(() => {
    if (!open) return;
    const onPointerDown = (e: PointerEvent) => {
      if (!rootRef.current?.contains(e.target as Node)) setOpen(false);
    };
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") setOpen(false);
    };
    document.addEventListener("pointerdown", onPointerDown);
    document.addEventListener("keydown", onKey);
    return () => {
      document.removeEventListener("pointerdown", onPointerDown);
      document.removeEventListener("keydown", onKey);
    };
  }, [open]);

  return (
    <div ref={rootRef} className={cx("rs-select", className)} {...props}>
      <button
        type="button"
        className="rs-dropdown"
        aria-haspopup="dialog"
        aria-expanded={open}
        onClick={() => setOpen((o) => !o)}
      >
        <span>{value ? format(value) : placeholder}</span>
        <Icon name="calendar" size={16} />
      </button>
      {open && (
        <div className="rs-menu" style={{ right: "auto" }}>
          <Calendar
            value={value}
            onSelect={(d) => {
              onChange?.(d);
              setOpen(false);
            }}
          />
        </div>
      )}
    </div>
  );
}

import * as React from "react";
import { cx } from "./cx";
import { Icon } from "./icon";

export interface CalendarProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "onSelect"> {
  value?: Date;
  onSelect?: (date: Date) => void;
  defaultMonth?: Date;
  /** 0 = Sunday, 1 = Monday. */
  weekStart?: 0 | 1;
}

const DOW = ["Mo", "Tu", "We", "Th", "Fr", "Sa", "Su"];

function sameDay(a: Date | undefined, b: Date): boolean {
  return (
    !!a && a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth() && a.getDate() === b.getDate()
  );
}

/** Month grid. Selected is ink; today is a hairline. */
export function Calendar({ value, onSelect, defaultMonth, weekStart = 1, className, ...props }: CalendarProps) {
  const [month, setMonth] = React.useState(() => {
    const base = value ?? defaultMonth ?? new Date();
    return new Date(base.getFullYear(), base.getMonth(), 1);
  });

  const first = new Date(month.getFullYear(), month.getMonth(), 1);
  const lead = (first.getDay() - weekStart + 7) % 7;
  const start = new Date(month.getFullYear(), month.getMonth(), 1 - lead);
  const days = Array.from({ length: 42 }, (_, i) => {
    const d = new Date(start);
    d.setDate(start.getDate() + i);
    return d;
  });
  const today = new Date();
  const title = month.toLocaleDateString("en", { month: "long", year: "numeric" });
  const dows = weekStart === 1 ? DOW : ["Su", ...DOW.slice(0, 6)];
  const shift = (delta: number) => setMonth(new Date(month.getFullYear(), month.getMonth() + delta, 1));

  return (
    <div className={cx("rs-cal", className)} {...props}>
      <div className="rs-cal-head">
        <span className="rs-cal-title" aria-live="polite">
          {title}
        </span>
        <span className="rs-cal-nav">
          <button type="button" className="rs-page" aria-label="Previous month" onClick={() => shift(-1)}>
            <Icon name="chevron-left" size={12} />
          </button>
          <button type="button" className="rs-page" aria-label="Next month" onClick={() => shift(1)}>
            <Icon name="chevron-right" size={12} />
          </button>
        </span>
      </div>
      <div className="rs-cal-grid" role="grid">
        {dows.map((d) => (
          <span key={d} className="rs-cal-dow" role="columnheader">
            {d}
          </span>
        ))}
        {days.map((d) => {
          const out = d.getMonth() !== month.getMonth();
          const selected = sameDay(value, d);
          return (
            <button
              key={d.toISOString()}
              type="button"
              className={cx(
                "rs-cal-day",
                out && "rs-cal-day-out",
                sameDay(today, d) && "rs-cal-day-today",
                selected && "rs-cal-day-selected",
              )}
              aria-pressed={selected}
              aria-label={d.toDateString()}
              onClick={() => {
                onSelect?.(d);
                if (out) setMonth(new Date(d.getFullYear(), d.getMonth(), 1));
              }}
            >
              {d.getDate()}
            </button>
          );
        })}
      </div>
    </div>
  );
}

import * as React from "react";
import { cx } from "./cx";
import {
  iconGroups,
  iconLabel,
  iconNames,
  marks,
  resolveIcon,
  type IconName,
  type IconRotate,
  type MarkEl,
} from "./icon-marks";

export { iconGroups, iconLabel, iconNames, resolveIcon };
export type { IconName, IconRotate };
export type { DrawnName, IconAlias, IconGroup } from "./icon-marks";

/**
 * Raster chrome marks. Vera 28 Aug 2026; optical recut 1 Sep 2026; R1 pairs 1 Sep 2026.
 *
 * 16×16 module, optical center 8,8. Line: stroke 1, fill none.
 * Filled: same figures, solid closed geometry, currentColor. Not a second library.
 * Cap butt, join miter, no rx. Hairline stays 1 CSS px at 12, 16, and 24.
 * Copied is check. Accordion down is chevron-right rotated 90°.
 * First five marks (copy, copied, chevron-left, chevron-right, close) stay as drawn,
 * except L/R chevrons take a measured +0.25y optical nudge toward 8,8.
 */
export const ICON_STROKE = 1;
export const ICON_VIEWBOX = 16;

export const iconInk = {
  fill: "none",
  stroke: "currentColor",
  strokeWidth: ICON_STROKE,
  strokeLinecap: "butt",
  strokeLinejoin: "miter",
  vectorEffect: "non-scaling-stroke",
} as const;

export const iconFill = {
  fill: "currentColor",
  stroke: "none",
} as const;

export type IconSize = 12 | 16 | 24;
export type IconVariant = "line" | "filled";

function isClosed(el: MarkEl): boolean {
  if (el.t === "rect" || el.t === "circle") return true;
  if (el.t === "path") return /z\s*$/i.test(el.d.trim());
  return false;
}

function inkFor(el: MarkEl, variant: IconVariant) {
  return variant === "filled" && isClosed(el) ? iconFill : iconInk;
}

function renderEl(el: MarkEl, key: number, variant: IconVariant): React.ReactNode {
  const ink = inkFor(el, variant);
  switch (el.t) {
    case "path":
      return <path key={key} d={el.d} {...ink} />;
    case "rect":
      return <rect key={key} x={el.x} y={el.y} width={el.w} height={el.h} {...ink} />;
    case "circle":
      return <circle key={key} cx={el.cx} cy={el.cy} r={el.r} {...ink} />;
    case "line":
      return <line key={key} x1={el.x1} y1={el.y1} x2={el.x2} y2={el.y2} {...ink} />;
  }
}

export interface IconProps extends Omit<React.SVGAttributes<SVGSVGElement>, "children" | "rotate"> {
  name: IconName;
  size?: IconSize;
  /** Line hairline, or filled kinship of the same figure. */
  variant?: IconVariant;
  /** Same mark, spun around 8,8. Accordion down is chevron-right at 90. */
  rotate?: IconRotate;
}

/** One mark. Size is the drawn square; the viewBox is always 16. */
export function Icon({ name, size = 16, variant = "line", rotate, className, ...props }: IconProps) {
  const resolved = resolveIcon(name);
  const turn = rotate ?? resolved.rotate;
  const nodes = marks[resolved.mark].map((el, i) => renderEl(el, i, variant));
  return (
    <svg
      className={cx("rs-icon", variant === "filled" && "rs-icon-filled", className)}
      viewBox="0 0 16 16"
      width={size}
      height={size}
      aria-hidden="true"
      {...iconInk}
      {...props}
    >
      {turn ? <g transform={`rotate(${turn} 8 8)`}>{nodes}</g> : nodes}
    </svg>
  );
}

/** Full family at 12, 16, and 24, line | filled, grouped. Optical center 8,8. */
export function IconCatalog({ className }: { className?: string }) {
  return (
    <div className={cx("rs-icon-catalog", className)}>
      {iconGroups.map((group) => (
        <section key={group.title} className="rs-icon-group">
          <h3 className="rs-icon-group-title">{group.title}</h3>
          <div className="rs-icon-grid">
            {group.names.map((mark) => (
              <div key={`${group.title}-${mark}`} className="rs-icon-cell">
                <div className="rs-icon-pair">
                  <div className="rs-icon-kin" data-variant="line">
                    <Icon name={mark} size={12} />
                    <Icon name={mark} size={16} />
                    <Icon name={mark} size={24} />
                  </div>
                  <div className="rs-icon-kin" data-variant="filled">
                    <Icon name={mark} size={12} variant="filled" />
                    <Icon name={mark} size={16} variant="filled" />
                    <Icon name={mark} size={24} variant="filled" />
                  </div>
                </div>
                <span className="rs-icon-label">{iconLabel(mark)}</span>
              </div>
            ))}
          </div>
        </section>
      ))}
    </div>
  );
}

/** Join class names, dropping falsy parts. */
export function cx(...parts: Array<string | false | null | undefined>): string {
  return parts.filter(Boolean).join(" ");
}

